}

have_cmd() {
  command -v "$1" >/dev/null 2>&1
}

is_integer() {
  value="${1:-}"
  [ -n "$value" ] || return 1
  case "$value" in
    -*) value="${value#-}" ;;
  esac
  [ -n "$value" ] || return 1
  case "$value" in
    *[!0-9]*) return 1 ;;
  esac
  return 0
}

is_unsigned_integer() {
  case "${1:-}" in
    ""|*[!0-9]*) return 1 ;;
  esac
  return 0
}

is_positive_number() {
  awk -v value="$1" 'BEGIN {
    exit !(value ~ /^[0-9]+([.][0-9]+)?$/ && value + 0 > 0)
  }'
}

need_root() {
  if [ "$(id -u 2>/dev/null || echo 1)" != "0" ]; then
    die "此操作需要 root 权限。请使用 root 用户或 sudo 运行。"
  fi
}

ensure_state_dir() {
  need_root
  # 子 shell 内收紧 umask，避免修改整个进程的全局 umask。
  (umask 077; mkdir -p "$STATE_DIR/backups" "$STATE_DIR/sessions" "$STATE_DIR/rolled-back") || return 1
  chmod 700 "$STATE_DIR" "$STATE_DIR/backups" "$STATE_DIR/sessions" "$STATE_DIR/rolled-back" 2>/dev/null || true
}

secure_temp_dir() {
