safe_report_text() {
  printf '%s' "${1:-}" | tr '\r\n\t,:"'"'"'' '        ' | cut -c 1-160
}

mask_report_peer() {
  value="${1:-}"
  [ -n "$value" ] || { echo ""; return 0; }
  case "$value" in
    http://\[*\]*|https://\[*\]*)
      inner="$(printf '%s' "$value" | sed 's#^[^[]*\[\([^]]*\)\].*#\1#')"
      first="${inner%%:*}"
      last="${inner##*:}"
      printf '%s\n' "$(safe_report_text "$first:...:$last")"
      return 0
      ;;
    *.*.*.*:*)
      # IPv4:端口——IPv4 段仍需打码，不能因带端口而整段进入报告。
      host_part="${value%%:*}"
      port_part="${value##*:}"
      if [ "${value%:*}" = "$host_part" ]; then
        masked_host="$(mask_report_peer "$host_part")"
        printf '%s\n' "$(safe_report_text "$masked_host:$port_part")"
        return 0
      fi
      first="${value%%:*}"
      last="${value##*:}"
      printf '%s\n' "$(safe_report_text "$first:...:$last")"
      return 0
      ;;
    *:*)
      first="${value%%:*}"
      last="${value##*:}"
      if [ -n "$first" ] && [ -n "$last" ] && [ "$first" != "$value" ]; then
        printf '%s\n' "$(safe_report_text "$first:...:$last")"
        return 0
      fi
      ;;
    *.*.*.*)
      masked="$(printf '%s\n' "$value" | awk -F. 'NF == 4 && $1 ~ /^[0-9]+$/ && $2 ~ /^[0-9]+$/ && $3 ~ /^[0-9]+$/ && $4 ~ /^[0-9]+$/ {print $1 "." $2 ".x.x"; found=1} END {if (!found) print ""}')"
      if [ -n "$masked" ]; then
        printf '%s\n' "$(safe_report_text "$masked")"
        return 0
      fi
      ;;
  esac
  printf '%s\n' "$(safe_report_text "$value")"
}

unique_path() {
  base_path="$1"
  candidate_path="$base_path"
  suffix=1
  while [ -e "$candidate_path" ]; do
    candidate_path="${base_path}-$suffix"
    suffix=$((suffix + 1))
  done
  printf '%s\n' "$candidate_path"
}

