# 显示宽度计算：中文等 CJK 字符占 2 列，ASCII 占 1 列
# 用 awk 按 UTF-8 字节范围统计 CJK 字符数，补齐到指定显示宽度
ui_pad() {
  text="$1"
  width="$2"
  # awk 仅返回显示宽度（CJK 字符算 2），补空格交给 shell printf，兼容 busybox awk
  disp=$(printf '%s' "$text" | awk '{
    s = $0
    disp = 0
    n = length(s)
    for (i = 1; i <= n; i++) {
      c = substr(s, i, 1)
      if (c < "\200") disp += 1
      else if (c >= "\300") disp += 2
    }
    print disp + 0
  }')
  [ -z "$disp" ] && disp=0
  pad=$((width - disp))
  if [ "$pad" -gt 0 ]; then
    printf '%s%*s' "$text" "$pad" ""
  else
    printf '%s' "$text"
  fi
}

