    "$color" "$number" "$COLOR_RESET" \
    "$COLOR_BOLD" "$(ui_pad "$title" 16)" "$COLOR_RESET" \
    "$COLOR_DIM" "$desc" "$COLOR_RESET"
}

trend_label() {
  current="$1"
  previous="$2"
  if [ -z "$previous" ]; then
    echo "建立基线"
  elif [ "$current" -lt "$previous" ]; then
    echo "重传下降"
  elif [ "$current" -gt "$previous" ]; then
    echo "重传上升"
  else
    echo "保持稳定"
  fi
}

next_action_label() {
  objective="$1"
  retr="$2"
  target_retr="$3"
  case "$objective" in
    throughput)
      if [ "$retr" -le "$target_retr" ]; then
        echo "重传可接受，继续尝试提高吞吐。"
      else
        echo "重传偏高，先收缩缓冲再测试。"
      fi
      ;;
    startup)
      echo "降低初始排队，优先改善短连接起速。"
      ;;
    *)
      if [ "$retr" -le "$target_retr" ]; then
        echo "已达到目标，保持当前参数。"
      else
        echo "降低排队和发送缓冲，继续压低重传。"
      fi
      ;;
  esac
}

