# BEGIN src/platform/detect.sh
# Module: src/platform/detect.sh
detect_os() {
  OS_ID="unknown"
  OS_NAME="Unknown"
  OS_FAMILY="linux"
  PKG_MANAGER="none"

  if [ "$(uname -s 2>/dev/null || echo unknown)" = "Darwin" ]; then
    OS_ID="macos"
    OS_NAME="macOS"
    OS_FAMILY="macos"
    PKG_MANAGER="brew"
    return 0
  fi

  if [ -f /etc/openwrt_release ]; then
    OS_ID="openwrt"
    OS_NAME="OpenWrt"
    OS_FAMILY="openwrt"
    PKG_MANAGER="opkg"
    return 0
  fi

  if [ -f /etc/os-release ]; then
    # shellcheck disable=SC1091
    . /etc/os-release
    OS_ID="${ID:-unknown}"
    OS_NAME="${PRETTY_NAME:-$OS_ID}"
  fi

  case "$OS_ID" in
    debian|ubuntu|linuxmint|raspbian)
      PKG_MANAGER="apt"
      ;;
    almalinux|rocky|centos|fedora|rhel)
      if have_cmd dnf; then PKG_MANAGER="dnf"; else PKG_MANAGER="yum"; fi
      ;;
    openwrt)
      OS_FAMILY="openwrt"
      PKG_MANAGER="opkg"
      ;;
    *)
      if have_cmd apt-get; then PKG_MANAGER="apt"; fi
      if have_cmd dnf; then PKG_MANAGER="dnf"; fi
      if have_cmd yum; then PKG_MANAGER="yum"; fi
      if have_cmd opkg; then PKG_MANAGER="opkg"; OS_FAMILY="openwrt"; fi
      ;;
  esac
}

platform_is_read_only() {
  detect_os
  [ "$OS_FAMILY" = "macos" ]
}

install_pkg() {
  pkg="$1"
  if [ "${DRY_RUN:-0}" = "1" ]; then
    info "[dry-run] 将通过 $PKG_MANAGER 安装 $pkg"
    return 0
  fi
  case "$PKG_MANAGER" in
    apt)
      if [ "$pkg" = "iperf3" ] && have_cmd debconf-set-selections; then
        printf '%s\n' "iperf3 iperf3/start_daemon boolean false" | debconf-set-selections
      fi
      DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a apt-get update
      DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a UCF_FORCE_CONFFOLD=1 \
        apt-get install -y \
          -o Dpkg::Options::=--force-confdef \
          -o Dpkg::Options::=--force-confold \
          "$pkg"
      ;;
    dnf)
      dnf install -y "$pkg"
      ;;
    yum)
      yum install -y "$pkg"
      ;;
    opkg)
      opkg update
      opkg install "$pkg"
      ;;
    brew)
      brew install "$pkg"
      ;;
    *)
      return 1
      ;;
  esac
}

ensure_dependency() {
  cmd="$1"
  pkg="$2"
  if have_cmd "$cmd"; then
    return 0
  fi
  if [ "${DRY_RUN:-0}" = "1" ]; then
    info "缺少 $cmd，预览通过 $PKG_MANAGER 安装 $pkg"
    install_pkg "$pkg" || die "当前系统无法自动安装 $pkg。"
    return 0
  fi
  if [ "${ASSUME_YES:-0}" = "1" ]; then
    info "缺少 $cmd，尝试通过 $PKG_MANAGER 安装 $pkg"
    install_pkg "$pkg" || die "无法自动安装 $pkg，请手动安装后重试。"
    return 0
  fi
  if has_interactive_input; then
    if ! prompt_read "缺少 $cmd，是否立即通过 $PKG_MANAGER 安装 $pkg？[y/N] "; then
      install_answer=""
    else
      install_answer="$PROMPT_REPLY"
    fi
    case "$install_answer" in
      y|Y)
        install_pkg "$pkg" || die "无法自动安装 $pkg，请手动安装后重试。"
        return 0
        ;;
    esac
  fi
  warn "缺少 $cmd。可使用 --yes 自动安装，或手动安装 $pkg。"
  return 1
}

install_runtime_deps() {
  detect_os
  case "$OS_FAMILY" in
    openwrt)
      ensure_dependency iperf3 iperf3 || true
      ensure_dependency curl curl || true
      ensure_openwrt_tcp_accel_deps
      ;;
    macos)
      ensure_dependency iperf3 iperf3 || true
      ensure_dependency curl curl || true
      ;;
    *)
      ensure_dependency iperf3 iperf3 || true
      ensure_dependency curl curl || true
      ;;
  esac
}

doctor() {
  detect_os
  echo "$APP_NAME $APP_VERSION"
  echo "仓库：$REPO_URL"
  echo "系统：$OS_NAME"
  echo "系统族：$OS_FAMILY"
  echo "包管理器：$PKG_MANAGER"
  echo "内核：$(uname -a 2>/dev/null || echo unknown)"
  echo
  echo "依赖状态："
  for cmd in iperf3 curl wget sysctl tc ip python3; do
    if have_cmd "$cmd"; then
      echo "  $cmd: $(command -v "$cmd")"
    else
      echo "  $cmd: 缺失"
    fi
  done
  echo
  echo "端口配置：Agent=$AGENT_PORT iperf3=$IPERF_PORT TTL=${SESSION_TTL}s"
  echo "状态目录：$STATE_DIR"
  echo "sysctl 文件：$SYSCTL_FILE"
  echo
  openwrt_advice
}

install_only() {
  need_root
  install_runtime_deps
  echo "依赖安装/检查完成。"
}

# END src/platform/detect.sh

# BEGIN src/platform/linux.sh
# Module: src/platform/linux.sh
preferred_qdisc() {
  detect_os
  current_qdisc="$(sysctl -n net.core.default_qdisc 2>/dev/null || true)"
  if [ "$OS_FAMILY" = "openwrt" ]; then
    case "$current_qdisc" in
      cake|fq_codel|fq) echo "$current_qdisc" ;;
      *) echo "fq_codel" ;;
    esac
    return 0
  fi
  echo "fq"
}

preferred_congestion_control() {
  available="$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)"
  current="$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || true)"
  case " $available " in
    *" bbr "*) ;;
    *) ;;
  esac
  case " $available " in
    *" bbr "*) echo "bbr"; return 0 ;;
  esac
  case "$current" in
    bbr|cubic|reno) echo "$current"; return 0 ;;
  esac
  case " $available " in
    *" cubic "*) echo "cubic"; return 0 ;;
    *" reno "*) echo "reno"; return 0 ;;
  esac
  echo ""
}

ensure_tcp_baseline() {
  # 基础拥塞控制和 qdisc 必须与其他参数一起进入事务，不能在基线测速前单独写入。
  return 0
}

apply_vps_adapt_values() {
  congestion="$1"
  mtu_probing="$2"
  slow_start="$3"
  rmem_max="$4"
  wmem_max="$5"
  notsent_lowat="$6"
  limit_output="$7"

  need_root
  case "$congestion" in bbr|cubic|reno) ;; *) die "非法拥塞控制：$congestion" ;; esac
  validate_bool_number "$mtu_probing" || die "非法 tcp_mtu_probing：$mtu_probing"
  validate_bool_number "$slow_start" || die "非法 tcp_slow_start_after_idle：$slow_start"
  validate_positive_int_range "$rmem_max" 1048576 268435456 || die "非法 rmem_max：$rmem_max"
  validate_positive_int_range "$wmem_max" 1048576 268435456 || die "非法 wmem_max：$wmem_max"
  validate_positive_int_range "$notsent_lowat" 16384 "$(max_notsent_lowat)" || die "非法 tcp_notsent_lowat：$notsent_lowat"
  validate_positive_int_range "$limit_output" 131072 4194304 || die "非法 tcp_limit_output_bytes：$limit_output"

  if [ "${DRY_RUN:-0}" = "1" ]; then
    info "[dry-run] VPS 将写入：cc=$congestion mtu=$mtu_probing slow_start=$slow_start rmem=$rmem_max wmem=$wmem_max notsent=$notsent_lowat limit=$limit_output"
    return 0
  fi

  backup_dir="$(manual_backup_begin "ipv6-vps")"
  candidate="$backup_dir/vps-adapt.candidate"
  cat > "$candidate" <<EOF
# TCP-optimization: IPv6 peer adaptation profile.
# This file is managed by tcp-tune.sh; rollback data: $backup_dir
net.ipv4.tcp_congestion_control = $congestion
net.ipv4.tcp_mtu_probing = $mtu_probing
net.ipv4.tcp_slow_start_after_idle = $slow_start
net.core.rmem_max = $rmem_max
net.core.wmem_max = $wmem_max
net.ipv4.tcp_rmem = 4096 87380 $rmem_max
net.ipv4.tcp_wmem = 4096 16384 $wmem_max
net.ipv4.tcp_notsent_lowat = $notsent_lowat
net.ipv4.tcp_limit_output_bytes = $limit_output
EOF
  if ! apply_sysctl_transaction "$VPS_ADAPT_FILE" "$candidate" "$backup_dir" vps-adapt-target; then
    restore_manual_backup "$backup_dir" >/dev/null 2>&1 || true
    DIE_EXIT_CODE="$EXIT_APPLY" die "VPS 适配事务加载或验证失败，已回滚；备份目录：$backup_dir"
  fi
  info "VPS 适配参数已保存并加载：$VPS_ADAPT_FILE"
  info "备份目录：$backup_dir"
}

vps_adapt_profile() {
  profile="$1"
  case "$profile" in
    cubic-safe|balanced)
      apply_vps_adapt_values cubic 1 0 67108864 67108864 "$(max_notsent_lowat)" 1048576
      ;;
    bbr-fast)
      apply_vps_adapt_values bbr 1 0 67108864 67108864 "$(max_notsent_lowat)" 1048576
      ;;
    *)
      die "未知 VPS 适配预设：$profile"
      ;;
  esac
}

# END src/platform/linux.sh

# BEGIN src/platform/openwrt.sh
# Module: src/platform/openwrt.sh
ensure_openwrt_tcp_accel_deps() {
  [ "${DRY_RUN:-0}" = "1" ] && return 0
  [ "${OS_FAMILY:-}" = "openwrt" ] || return 0
  [ "$(id -u 2>/dev/null || echo 1)" = "0" ] || return 0
  have_cmd opkg || return 0
  available="$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)"
  case " $available " in
    *" bbr "*) return 0 ;;
  esac
  opkg update >/dev/null 2>&1 || true
  opkg install kmod-tcp-bbr >/dev/null 2>&1 || true
  if have_cmd modprobe; then modprobe tcp_bbr >/dev/null 2>&1 || true; fi
}

openwrt_key_allowed() {
  case "$1" in
    net.ipv4.tcp_mtu_probing|net.ipv4.tcp_slow_start_after_idle|net.ipv4.tcp_notsent_lowat|net.ipv4.tcp_limit_output_bytes|net.ipv4.tcp_congestion_control|net.core.default_qdisc) return 0 ;;
    *) return 1 ;;
  esac
}

apply_openwrt_minimal_values() {
  mtu_probing="$1"
  slow_start="$2"
  notsent_lowat="$3"
  limit_output="$4"

  need_root
  validate_bool_number "$mtu_probing" || die "非法 tcp_mtu_probing：$mtu_probing"
  validate_bool_number "$slow_start" || die "非法 tcp_slow_start_after_idle：$slow_start"
  validate_positive_int_range "$notsent_lowat" 16384 "$(max_notsent_lowat)" || die "非法 tcp_notsent_lowat：$notsent_lowat"
  validate_positive_int_range "$limit_output" 131072 4194304 || die "非法 tcp_limit_output_bytes：$limit_output"

  if [ "${DRY_RUN:-0}" = "1" ]; then
    info "[dry-run] OpenWrt 将最小写入：mtu=$mtu_probing slow_start=$slow_start notsent=$notsent_lowat limit=$limit_output"
    return 0
  fi

  backup_dir="$(manual_backup_begin "ipv6-openwrt")"
  candidate="$backup_dir/openwrt-minimal.candidate"
  cat > "$candidate" <<EOF
# TCP-optimization: minimal local overrides for verified IPv6 peer paths.
# This file does not touch firewall, WAN, DNS, DHCP or proxy services.
net.ipv4.tcp_mtu_probing = $mtu_probing
net.ipv4.tcp_slow_start_after_idle = $slow_start
net.ipv4.tcp_notsent_lowat = $notsent_lowat
net.ipv4.tcp_limit_output_bytes = $limit_output
EOF
  if ! apply_sysctl_transaction "$OPENWRT_MINIMAL_FILE" "$candidate" "$backup_dir" openwrt-minimal-target; then
    restore_manual_backup "$backup_dir" >/dev/null 2>&1 || true
    DIE_EXIT_CODE="$EXIT_APPLY" die "OpenWrt 最小参数事务加载或验证失败，已回滚；备份目录：$backup_dir"
  fi
  info "OpenWrt 最小参数已保存并加载：$OPENWRT_MINIMAL_FILE"
  info "备份目录：$backup_dir"
}

# END src/platform/openwrt.sh

