# BEGIN src/tuning/benchmark.sh
# Module: src/tuning/benchmark.sh
public_ip() {
  if have_cmd curl; then
    curl -4fsS --max-time 5 https://icanhazip.com 2>/dev/null | tr -d ' \r\n' || true
  elif have_cmd wget; then
    wget -qO- --timeout=5 https://icanhazip.com 2>/dev/null | tr -d ' \r\n' || true
  fi
}

local_lan_ipv4() {
  if [ "${OS_FAMILY:-}" = "openwrt" ] || [ -f /etc/openwrt_release ]; then
    found_lan_ip=""
    if have_cmd ip; then
      found_lan_ip="$(for dev in br-lan lan eth0 eth1; do ip -4 addr show dev "$dev" 2>/dev/null; done | awk '/inet / {split($2,a,"/"); if (a[1] !~ /^127[.]/ && a[1] !~ /^169[.]254[.]/) {print a[1]; exit}}')"
    fi
    if [ -n "$found_lan_ip" ]; then
      echo "$found_lan_ip"
      return 0
    fi
  fi
  if have_cmd ip; then
    ip -4 route get 1.1.1.1 2>/dev/null | awk '
      {
        for (i = 1; i <= NF; i++) {
          if ($i == "src" && (i + 1) <= NF) {
            print $(i + 1)
            exit
          }
        }
      }
    ' | awk '/^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ {print; exit}'
    return 0
  fi
  if have_cmd route && have_cmd ipconfig; then
    interface="$(route -n get default 2>/dev/null | awk '/interface:/ {print $2; exit}')"
    if [ -n "$interface" ]; then
      ipconfig getifaddr "$interface" 2>/dev/null || true
      return 0
    fi
  fi
  hostname -I 2>/dev/null | awk '{for (i = 1; i <= NF; i++) if ($i ~ /^[0-9]+\./) {print $i; exit}}' || true
}

objective_label() {
  case "$1" in
    throughput) echo "吞吐优先" ;;
    startup) echo "快速起速" ;;
    *) echo "重传优先" ;;
  esac
}

direction_label() {
  [ "$1" = "1" ] && echo "下载（服务端 → 本机）" || echo "上传（本机 → 服务端）"
}

format_rate() {
  case "${1:-unknown}" in unknown|unsupported|failed) printf '%s\n' "${1:-unknown}"; return 0 ;; esac
  awk -v bps="$1" 'BEGIN {
    if (bps >= 1000000000) printf "%.2f Gbps\n", bps / 1000000000
    else printf "%.1f Mbps\n", bps / 1000000
  }'
}

format_count() {
  case "${1:-unknown}" in unknown|unsupported|failed) printf '%s\n' "${1:-unknown}"; return 0 ;; esac
  awk -v value="$1" 'BEGIN {
    text = sprintf("%.0f", value)
    output = ""
    while (length(text) > 3) {
      output = "," substr(text, length(text) - 2) output
      text = substr(text, 1, length(text) - 3)
    }
    print text output
  }'
}

percent_delta() {
  before="$1"
  after="$2"
  awk -v before="$before" -v after="$after" 'BEGIN {
    if (before <= 0) {
      print "建立基线"
      exit
    }
    delta = (after - before) * 100 / before
    if (delta > 0) printf "+%.0f%%\n", delta
    else printf "%.0f%%\n", delta
  }'
}

progress_steps() {
  round="$1"
  rounds="$2"
  printf "  %s%s连接测试%s → %s分析结果%s → %s应用调整%s → %s复测确认%s\n" \
    "$COLOR_BOLD" "$COLOR_GREEN" "$COLOR_RESET" \
    "$COLOR_CYAN" "$COLOR_RESET" \
    "$COLOR_CYAN" "$COLOR_RESET" \
    "$COLOR_DIM" "$COLOR_RESET"
  printf "  %s轮次 %s/%s%s\n" "$COLOR_DIM" "$round" "$rounds" "$COLOR_RESET"
}

start_iperf_server() {
  ensure_dependency iperf3 iperf3 || die "缺少 iperf3，无法启动测试服务。"
  port="$1"
  if pgrep -f "iperf3.*-s.*-p[[:space:]]*$port([^0-9]|\$)" >/dev/null 2>&1; then
    info "检测到端口 $port 已有 iperf3 server，将复用且不会由本工具停止。"
    return 0
  fi
  nohup iperf3 -s -p "$port" > "$STATE_DIR/iperf3-$port.log" 2>&1 &
  iperf_pid="$!"
  atomic_write_line "$STATE_DIR/iperf3-$port.pid" "$iperf_pid"
  write_process_manifest "$STATE_DIR/iperf3-$port.manifest" "$iperf_pid" "${TCP_TUNE_SESSION_ID:-standalone}" "iperf3" "$port" || {
    kill "$iperf_pid" 2>/dev/null || true
    rm -f "$STATE_DIR/iperf3-$port.pid"
    die "无法记录 iperf3 进程身份。"
  }
  info "iperf3 server 已启动，端口：$port"
}

stop_iperf_server() {
  port="$1"
  if [ -f "$STATE_DIR/iperf3-$port.manifest" ]; then
    pid="$(manifest_value "$STATE_DIR/iperf3-$port.manifest" pid)"
    if stop_verified_process "$STATE_DIR/iperf3-$port.manifest" "${TCP_TUNE_SESSION_ID:-}"; then
      rm -f "$STATE_DIR/iperf3-$port.pid" "$STATE_DIR/iperf3-$port.manifest"
      info "已停止 iperf3 server：$pid"
    else
      warn "iperf3 进程身份不匹配，未终止 PID $pid。"
      return 1
    fi
  else
    info "未找到本工具记录的 iperf3 manifest，未停止端口 $port 上的其他进程。"
  fi
}

active_iperf_client_manifest() {
  printf '%s/iperf3-client-%s.manifest\n' "$STATE_DIR" "$$"
}

stop_active_iperf_client() {
  active_manifest="$(active_iperf_client_manifest)"
  [ -f "$active_manifest" ] || return 0
  stop_verified_process "$active_manifest" "client-$$" >/dev/null 2>&1 || return 1
  rm -f "$active_manifest"
}

run_owned_iperf_client() {
  ensure_state_dir
  active_manifest="$(active_iperf_client_manifest)"
  "$@" &
  client_pid=$!
  if ! write_process_manifest "$active_manifest" "$client_pid" "client-$$" iperf3 "$port"; then
    kill "$client_pid" 2>/dev/null || true
    wait "$client_pid" 2>/dev/null || true
    return 1
  fi
  if wait "$client_pid"; then client_rc=0; else client_rc=$?; fi
  rm -f "$active_manifest"
  return "$client_rc"
}

run_iperf_client() {
  host="$1"
  port="$2"
  reverse="$3"
  seconds="$4"
  bind_ip="${5:-}"
  parallel="${6:-1}"
  [ -n "$host" ] || die "iperf3 需要 host"
  validate_port_value "$port" || die "iperf3 port 必须在 1 和 65535 之间。"
  case "$reverse" in 0|1) ;; *) die "iperf3 reverse 必须是 0 或 1。" ;; esac
  validate_positive_int_range "$seconds" 1 86400 || die "iperf3 seconds 必须是正整数。"
  validate_positive_int_range "$parallel" 1 64 || die "iperf3 parallel 必须是 1 到 64 的正整数。"
  ensure_dependency iperf3 iperf3 || die "缺少 iperf3，无法测试。"
  # 只在字面地址的地址族明确冲突时清空；合法 IPv6 bind 必须保留。
  if [ -n "$bind_ip" ]; then
    case "$host" in
      *:*) case "$bind_ip" in *:*) : ;; *) bind_ip="" ;; esac ;;
      [0-9]*.[0-9]*.[0-9]*.[0-9]*) case "$bind_ip" in *:*) bind_ip="" ;; esac ;;
    esac
  fi
  set -- iperf3 -c "$host" -p "$port"
  [ -n "$bind_ip" ] && set -- "$@" -B "$bind_ip"
  [ "$reverse" = "1" ] && set -- "$@" -R
  set -- "$@" -t "$seconds"
  [ "$parallel" -gt 1 ] && set -- "$@" -P "$parallel"
  set -- "$@" -J
  # 不使用 -O，首个 interval 才能代表真实连接起速；随机波动由多样本中位数处理。
  run_owned_iperf_client "$@"
}

numeric_median() {
  sort -n | awk '{v[NR]=$1} END {if (NR==0) exit 1; if (NR%2) print v[(NR+1)/2]; else printf "%.0f\n", (v[NR/2]+v[NR/2+1])/2}'
}

sample_spread_percent() {
  sort -n | awk 'NR==1{min=$1} {max=$1; sum+=$1; n++} END {if(!n||sum<=0){print 0; exit}; mean=sum/n; printf "%.0f\n", (max-min)*100/mean}'
}

measure_iperf_samples() {
  host="$1"; port="$2"; reverse="$3"; seconds="$4"; bind_ip="${5:-}"; parallel="${6:-1}"
  count="${7:-$TCP_TUNE_SAMPLE_COUNT}"
  validate_positive_int_range "$count" 1 7 || return 1
  temp_dir="$(secure_temp_dir tcp-tune-samples)" || return 1
  samples="$temp_dir/metrics.tsv"
  : > "$samples"
  run=1
  while [ "$run" -le "$count" ]; do
    json="$(run_iperf_client "$host" "$port" "$reverse" "$seconds" "$bind_ip" "$parallel" 2>/dev/null || true)"
    if [ -z "$json" ] || ! printf '%s' "$json" | grep -q '"end"'; then rm -f "$samples"; rmdir "$temp_dir" 2>/dev/null || true; return 1; fi
    bps="$(printf '%s\n' "$json" | extract_bps 2>/dev/null || true)"
    retr="$(printf '%s\n' "$json" | extract_retransmits 2>/dev/null || true)"
    first="$(printf '%s\n' "$json" | extract_first_interval_bps 2>/dev/null || true)"
    if ! is_unsigned_integer "$bps" || ! is_unsigned_integer "$retr" || ! is_unsigned_integer "$first"; then rm -f "$samples"; rmdir "$temp_dir" 2>/dev/null || true; return 1; fi
    printf '%s\t%s\t%s\n' "$bps" "$retr" "$first" >> "$samples"
    run=$((run + 1))
  done
  spread="$(cut -f1 "$samples" | sample_spread_percent)"
  if [ "$spread" -gt "$TCP_TUNE_MAX_SPREAD_PERCENT" ] && [ "$count" -ge 3 ]; then
    extra=0
    while [ "$extra" -lt 2 ]; do
      json="$(run_iperf_client "$host" "$port" "$reverse" "$seconds" "$bind_ip" "$parallel" 2>/dev/null || true)"
      bps="$(printf '%s\n' "$json" | extract_bps 2>/dev/null || true)"
      retr="$(printf '%s\n' "$json" | extract_retransmits 2>/dev/null || true)"
      first="$(printf '%s\n' "$json" | extract_first_interval_bps 2>/dev/null || true)"
      if ! is_unsigned_integer "$bps" || ! is_unsigned_integer "$retr" || ! is_unsigned_integer "$first"; then break; fi
      printf '%s\t%s\t%s\n' "$bps" "$retr" "$first" >> "$samples"
      extra=$((extra + 1))
    done
    spread="$(cut -f1 "$samples" | sample_spread_percent)"
  fi
  if [ "$spread" -gt "$TCP_TUNE_MAX_SPREAD_PERCENT" ]; then
    rm -f "$samples"; rmdir "$temp_dir" 2>/dev/null || true
    return 2
  fi
  median_bps="$(cut -f1 "$samples" | numeric_median)"
  median_retr="$(cut -f2 "$samples" | numeric_median)"
  median_first="$(cut -f3 "$samples" | numeric_median)"
  rm -f "$samples"; rmdir "$temp_dir" 2>/dev/null || true
  printf '%s\t%s\t%s\t%s\n' "$median_bps" "$median_retr" "$median_first" "$spread"
}

run_iperf3_speedtest() {
  host="$1"
  port="$2"
  clear_screen
  print_header "iperf3 速度测试"
  ui_subtitle "简单测速，不修改任何参数"
  echo
  ui_section "测试参数"
  ui_row "对端地址" "$host"
  ui_row "端口" "$port"
  ui_row "测试方向" "下载（服务端 → 本机）"
  ui_row "测试时长" "10秒"
  case "$host" in
    *:*) ui_note "IPv6" "检测到 IPv6 地址，使用 IPv6 测速" ;;
  esac
  echo
  ui_note "状态" "正在测速..."
  ensure_dependency iperf3 iperf3 || { warn "缺少 iperf3"; return 1; }
  echo
  if iperf3 -c "$host" -p "$port" -R -t 10; then
    echo
    ui_section "测速完成"
  else
    echo
    warn "测速失败，请检查对端 iperf3 服务是否运行。"
  fi
}

# END src/tuning/benchmark.sh

# BEGIN src/tuning/iperf-parser.sh
# Module: src/tuning/iperf-parser.sh
iperf_python_field() {
  field="$1"
  python3 -c '
import json, sys
d=json.load(sys.stdin)
field=sys.argv[1]
end=d.get("end") or {}
intervals=d.get("intervals") or []
value=None
if field == "bps":
    value=(end.get("sum_received") or {}).get("bits_per_second")
    if value is None:
        vals=[(item.get("receiver") or {}).get("bits_per_second") for item in end.get("streams") or []]
        vals=[v for v in vals if v is not None]
        if vals: value=sum(vals)
    if value is None: value=(end.get("sum") or {}).get("bits_per_second")
elif field == "retrans":
    value=(end.get("sum_sent") or {}).get("retransmits")
    if value is None:
        vals=[(item.get("sender") or {}).get("retransmits") for item in end.get("streams") or []]
        vals=[v for v in vals if v is not None]
        if vals: value=sum(vals)
elif field == "first":
    if intervals:
        first=intervals[0] or {}
        value=(first.get("sum") or first.get("sum_received") or first.get("sum_sent") or {}).get("bits_per_second")
        if value is None:
            vals=[item.get("bits_per_second") for item in first.get("streams") or []]
            vals=[v for v in vals if v is not None]
            if vals: value=sum(vals)
if value is None: sys.exit(2)
try: value=float(value)
except (TypeError, ValueError): sys.exit(2)
if value < 0: sys.exit(2)
print(int(value))
' "$field"
}

jsonfilter_number() {
  expression="$1"
  jsonfilter -e "$expression" 2>/dev/null | awk '
    { for (i=1; i<=NF; i++) { if ($i !~ /^[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$/) exit 2; value=$i; count++ } }
    END { if (count != 1) exit 2; printf "%.0f\n", value }
  '
}

jsonfilter_sum() {
  expression="$1"
  jsonfilter -e "$expression" 2>/dev/null | awk '
    { for (i=1; i<=NF; i++) { if ($i !~ /^[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$/) exit 2; total+=$i; count++ } }
    END { if (count < 1) exit 2; printf "%.0f\n", total }
  '
}

iperf_jsonfilter_field() {
  field="$1"
  case "$field" in
    bps)
      jsonfilter_number '@.end.sum_received.bits_per_second' && return 0
      jsonfilter_sum '@.end.streams[*].receiver.bits_per_second' && return 0
      jsonfilter_number '@.end.sum.bits_per_second' && return 0
      ;;
    retrans)
      jsonfilter_number '@.end.sum_sent.retransmits' && return 0
      jsonfilter_sum '@.end.streams[*].sender.retransmits' && return 0
      ;;
    first)
      jsonfilter_number '@.intervals[0].sum.bits_per_second' && return 0
      jsonfilter_sum '@.intervals[0].streams[*].bits_per_second' && return 0
      ;;
  esac
  return 2
}

# 最后降级只接受多行 pretty JSON，并只读取明确的聚合对象。
# 紧凑 JSON 或缺少聚合对象时显式失败，避免从 P4 streams 猜最后一个字段。
iperf_awk_field() {
  field="$1"
  awk -v wanted="$field" '
    NR == 1 && $0 ~ /[{].*[}]/ { compact=1 }
    # 状态切换只认对象/数组开括号：stream 里的数值字段 "end": 1.000315 不得改变解析状态。
    /"intervals"[[:space:]]*:[[:space:]]*\[/ { in_intervals=1; in_end=0 }
    in_intervals && /"sum"[[:space:]]*:[[:space:]]*[{]/ && first_bps=="" { interval_sum=1; next }
    interval_sum && /"bits_per_second"[[:space:]]*:/ {
      line=$0; sub(/^.*"bits_per_second"[[:space:]]*:[[:space:]]*/, "", line); sub(/[^0-9.eE+-].*$/, "", line)
      if (line ~ /^[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$/) first_bps=line
      interval_sum=0
    }
    /"end"[[:space:]]*:[[:space:]]*[{]/ { in_end=1; in_intervals=0 }
    in_end && /"sum_received"[[:space:]]*:/ { block="received"; next }
    in_end && /"sum_sent"[[:space:]]*:/ { block="sent"; next }
    in_end && /"sum"[[:space:]]*:/ { block="sum"; next }
    in_end && /"bits_per_second"[[:space:]]*:/ {
      line=$0; sub(/^.*"bits_per_second"[[:space:]]*:[[:space:]]*/, "", line); sub(/[^0-9.eE+-].*$/, "", line)
      if (line ~ /^[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$/) {
        if (block=="received" && received_bps=="") received_bps=line
        else if (block=="sum" && sum_bps=="") sum_bps=line
      }
    }
    in_end && block=="sent" && /"retransmits"[[:space:]]*:/ {
      line=$0; sub(/^.*"retransmits"[[:space:]]*:[[:space:]]*/, "", line); sub(/[^0-9].*$/, "", line)
      if (line ~ /^[0-9]+$/ && retrans=="") retrans=line
    }
    /^[[:space:]]*}[,]?[[:space:]]*$/ { block=""; interval_sum=0 }
    END {
      if (compact) exit 2
      if (wanted=="bps") value=(received_bps!="" ? received_bps : sum_bps)
      else if (wanted=="retrans") value=retrans
      else if (wanted=="first") value=first_bps
      if (value=="") exit 2
      printf "%.0f\n", value
    }
  '
}

extract_iperf_field() {
  field="$1"
  if have_cmd python3; then iperf_python_field "$field"; return; fi
  if have_cmd jsonfilter; then iperf_jsonfilter_field "$field"; return; fi
  iperf_awk_field "$field"
}

extract_retransmits() { extract_iperf_field retrans; }
extract_bps() { extract_iperf_field bps; }
extract_first_interval_bps() { extract_iperf_field first; }

iperf_metric_or_unknown() {
  field="$1"
  value="$(extract_iperf_field "$field" 2>/dev/null)" || value=""
  if is_unsigned_integer "$value"; then printf '%s\n' "$value"; else printf 'unknown\n'; fi
}

# END src/tuning/iperf-parser.sh

# BEGIN src/tuning/metrics.sh
# Module: src/tuning/metrics.sh
objective_numbers_regressed() {
  objective="$1"
  first_bps="${2:-0}"
  final_bps="${3:-0}"
  first_retr="${4:-0}"
  final_retr="${5:-0}"
  first_startup_bps="${6:-0}"
  final_startup_bps="${7:-0}"
  target_retr="${8:-0}"
  awk -v objective="$objective" -v fb="$first_bps" -v lb="$final_bps" \
      -v fr="$first_retr" -v lr="$final_retr" -v fs="$first_startup_bps" \
      -v ls="$final_startup_bps" -v target="$target_retr" '
    BEGIN {
      bad = 0
      retr_limit = fr * 1.20
      if (retr_limit < fr + 10) retr_limit = fr + 10
      if (objective == "retrans") {
        if (fb > 0 && lb < fb * 0.95) bad = 1
        if (fs > 0 && ls < fs * 0.90) bad = 1
        if (lr > target && fr > 0 && lr > fr) bad = 1
      } else if (objective == "throughput") {
        if (fb > 0 && lb < fb * 0.95) bad = 1
        if (lr > retr_limit) bad = 1
        if (fs > 0 && ls < fs * 0.90) bad = 1
      } else {
        if (fs > 0 && ls < fs * 0.90) bad = 1
        if (fb > 0 && lb < fb * 0.90) bad = 1
        if (lr > retr_limit) bad = 1
      }
      exit !bad
    }
  '
}

objective_step_improved() {
  objective="$1"
  before_bps="${2:-0}"
  after_bps="${3:-0}"
  before_retr="${4:-0}"
  after_retr="${5:-0}"
  before_startup_bps="${6:-0}"
  after_startup_bps="${7:-0}"
  target_retr="${8:-0}"
  awk -v objective="$objective" -v bb="$before_bps" -v ab="$after_bps" \
      -v br="$before_retr" -v ar="$after_retr" -v bs="$before_startup_bps" \
      -v as="$after_startup_bps" -v target="$target_retr" -v guard="${OBJECTIVE_GUARD_OK:-1}" '
    BEGIN {
      ok = 0
      retr_limit = br * 1.20
      if (retr_limit < br + 10) retr_limit = br + 10
      if (objective == "retrans") {
        if ((ar <= target || (br > 0 && ar <= br * 0.85)) && (bb <= 0 || ab >= bb * 0.95) && (bs <= 0 || as >= bs * 0.90)) ok = 1
      } else if (objective == "throughput") {
        if (bb > 0 && ab >= bb * 1.05 && ar <= retr_limit && (bs <= 0 || as >= bs * 0.90)) ok = 1
      } else {
        if (bs > 0 && as >= bs * 1.075 && (bb <= 0 || ab >= bb * 0.90) && ar <= retr_limit) ok = 1
      }
      if (guard != 1) ok = 0
      exit !ok
    }
  '
}

objective_run_succeeded() {
  objective="$1"
  first_bps="${2:-0}"
  final_bps="${3:-0}"
  first_retr="${4:-0}"
  final_retr="${5:-0}"
  first_startup_bps="${6:-0}"
  final_startup_bps="${7:-0}"
  target_retr="${8:-0}"
  awk -v objective="$objective" -v fb="$first_bps" -v lb="$final_bps" \
      -v fr="$first_retr" -v lr="$final_retr" -v fs="$first_startup_bps" \
      -v ls="$final_startup_bps" -v target="$target_retr" -v guard="${OBJECTIVE_GUARD_OK:-1}" '
    BEGIN {
      ok = 0
      retr_limit = fr * 1.20
      if (retr_limit < fr + 10) retr_limit = fr + 10
      if (objective == "retrans") {
        if ((lr <= target || (fr > 0 && lr <= fr * 0.85)) && (fb <= 0 || lb >= fb * 0.95) && (fs <= 0 || ls >= fs * 0.90)) ok = 1
      } else if (objective == "throughput") {
        if (fb > 0 && lb >= fb * 1.05 && lr <= retr_limit && (fs <= 0 || ls >= fs * 0.90)) ok = 1
      } else {
        if (fs > 0 && ls >= fs * 1.075 && (fb <= 0 || lb >= fb * 0.90) && lr <= retr_limit) ok = 1
      }
      if (guard != 1) ok = 0
      exit !ok
    }
  '
}

