# BEGIN src/tuning/profiles.sh
# Module: src/tuning/profiles.sh
profile_exists() {
  case "$1" in
    "近距轻载"|"近距高速"|"中距均衡"|"长距增强"|"远距大带宽") return 0 ;;
    near-light|near-fast|mid-balance|long-boost|far-bandwidth) return 0 ;;
    *) return 1 ;;
  esac
}

normalize_profile() {
  case "$1" in
    "近距轻载"|near-light) echo "近距轻载" ;;
    "近距高速"|near-fast) echo "近距高速" ;;
    "中距均衡"|mid-balance) echo "中距均衡" ;;
    "长距增强"|long-boost) echo "长距增强" ;;
    "远距大带宽"|far-bandwidth) echo "远距大带宽" ;;
    *) die "未知预设：$1" ;;
  esac
}

profile_values() {
  name="$(normalize_profile "$1")"
  # 输出: file_max rmem_max wmem_max rmem_min rmem_default rmem_max
  #        wmem_min wmem_default wmem_max adv_win_scale notsent_lowat
  case "$name" in
    "近距轻载")
      echo "6815744 67108864 33554432 4096 87380 67108864 4096 16384 33554432 1 49152"
      ;;
    "近距高速")
      echo "6815744 67108864 67108864 4096 87380 67108864 4096 16384 67108864 1 65536"
      ;;
    "中距均衡")
      echo "6815744 89653247 43033559 8192 87380 89653247 8192 65536 43033559 1 98304"
      ;;
    "长距增强")
      echo "6815744 105062399 50429951 8192 87380 105062399 8192 65536 50429951 1 131072"
      ;;
    "远距大带宽")
      echo "6815744 186777599 89653247 8192 87380 186777599 8192 65536 89653247 1 196608"
      ;;
  esac
}

profile_rtt_hint() {
  case "$(normalize_profile "$1")" in
    "近距轻载") echo "RTT < 30ms" ;;
    "近距高速") echo "RTT 30~70ms" ;;
    "中距均衡") echo "RTT 70~130ms" ;;
    "长距增强") echo "RTT 130~190ms" ;;
    "远距大带宽") echo "RTT > 190ms" ;;
  esac
}

profile_comment() {
  case "$(normalize_profile "$1")" in
    "近距轻载") echo "低延迟链路，优先控制发送队列和重传。" ;;
    "近距高速") echo "同区域或精品线路，适合较高下行和稳定短中距链路。" ;;
    "中距均衡") echo "跨境中等延迟，接收缓冲略大于发送缓冲。" ;;
    "长距增强") echo "亚太/跨海高带宽链路，适合较大 BDP。" ;;
    "远距大带宽") echo "欧美等高延迟链路，缓冲更大，低内存设备需谨慎。" ;;
  esac
}

list_profiles() {
  cat <<'EOF'
TCP 预设（按距离/延迟从近到远排列）：

1. 近距轻载    (RTT < 30ms)
   接收 64MiB / 发送 32MiB。低延迟链路，优先控制发送队列和重传。

2. 近距高速    (RTT 30~70ms)
   接收 64MiB / 发送 64MiB。同区域或精品线路，适合较高下行和稳定短中距链路。

3. 中距均衡    (RTT 70~130ms)
   接收约 85MiB / 发送约 41MiB。跨境中等延迟，接收缓冲略大于发送缓冲。

4. 长距增强    (RTT 130~190ms)
   接收约 100MiB / 发送约 48MiB。亚太/跨海高带宽链路，适合较大 BDP。

5. 远距大带宽  (RTT > 190ms)
   接收约 178MiB / 发送约 85MiB。欧美等高延迟链路，缓冲更大，低内存设备需谨慎。

英文别名: near-light, near-fast, mid-balance, long-boost, far-bandwidth
EOF
}

profile_summary() {
  profile="$(normalize_profile "$1")"
  values="$(profile_values "$profile")"
  # shellcheck disable=SC2086
  set -- $values
  rmem_max="$2"
  wmem_max="$3"
  printf '%s\t%s\t%s\t%s\t%s\n' "$profile" "$(profile_rtt_hint "$profile")" "$rmem_max" "$wmem_max" "$(profile_comment "$profile")"
}

format_mib() {
  bytes="${1:-0}"
  awk -v b="$bytes" 'BEGIN { printf "%.0fMiB", b / 1048576 }'
}

print_profile_summary() {
  profile="$(normalize_profile "$1")"
  values="$(profile_values "$profile")"
  # shellcheck disable=SC2086
  set -- $values
  rmem_max="$2"
  wmem_max="$3"
  ui_row "预设挡位" "$profile"
  ui_row "适用范围" "$(profile_rtt_hint "$profile")"
  ui_row "接收缓冲" "$(format_mib "$rmem_max")"
  ui_row "发送缓冲" "$(format_mib "$wmem_max")"
  ui_note "说明" "$(profile_comment "$profile")"
}

preset_by_number() {
  case "$1" in
    1) echo "近距轻载" ;;
    2) echo "近距高速" ;;
    3) echo "中距均衡" ;;
    4) echo "长距增强" ;;
    5) echo "远距大带宽" ;;
    *) return 1 ;;
  esac
}

memory_mb() {
  awk '/MemTotal/ {printf "%d\n", $2 / 1024; found=1} END {if (!found) print 1024}' /proc/meminfo 2>/dev/null || echo 1024
}

memory_cap_bytes() {
  memory_mb_value="$1"
  aggressive="${2:-0}"
  detect_os
  awk -v mem="$memory_mb_value" -v aggressive="$aggressive" -v platform="$OS_FAMILY" '
    function clamp(v, min, max) {
      if (v < min) return min
      if (v > max) return max
      return v
    }
    BEGIN {
      mem_bytes = mem * 1024 * 1024
      if (platform == "openwrt") {
        if (mem <= 128) cap = 4 * 1024 * 1024
        else if (mem <= 256) cap = 8 * 1024 * 1024
        else if (mem <= 512) cap = 16 * 1024 * 1024
        else if (mem <= 1024) cap = 32 * 1024 * 1024
        else cap = clamp(int(mem_bytes * 0.05), 4 * 1024 * 1024, 64 * 1024 * 1024)
        printf "%d\n", cap
        exit
      }
      if (mem <= 256) ratio = 0.06
      else if (mem <= 512) ratio = 0.08
      else if (mem <= 1024) ratio = 0.10
      else if (mem <= 2048) ratio = 0.12
      else ratio = 0.15
      if (aggressive == 1 && mem > 512) ratio += 0.03
      printf "%d\n", clamp(int(mem_bytes * ratio), 262144, 268435456)
    }
  '
}

recommend_values() {
  local_mbps="$1"
  peer_mbps="$2"
  rtt_ms="$3"
  memory_mb_value="$4"
  objective="$5"
  ramp_rate="${6:-0.79}"
  aggressive="${7:-0}"

  for numeric_value in "$local_mbps" "$peer_mbps" "$rtt_ms" "$memory_mb_value" "$ramp_rate"; do
    if ! is_positive_number "$numeric_value"; then
      echo "ERR invalid numeric input"
      return 0
    fi
  done
  case "$objective" in
    retrans|throughput|startup) ;;
    *)
      echo "ERR invalid objective"
      return 0
      ;;
  esac

  detect_os
  awk -v local="$local_mbps" -v peer="$peer_mbps" -v rtt="$rtt_ms" -v mem="$memory_mb_value" \
      -v objective="$objective" -v ramp="$ramp_rate" -v aggressive="$aggressive" -v platform="$OS_FAMILY" '
    function clamp(v, min, max) {
      if (v < min) return min
      if (v > max) return max
      return v
    }
    function ceil(v) {
      return int(v) == v ? v : int(v) + 1
    }
    BEGIN {
      if (local <= 0 || peer <= 0 || rtt <= 0 || mem <= 0) {
        print "ERR invalid numeric input"
        exit
      }

      min_bw = local < peer ? local : peer
      # Mbps 使用 SI 单位（1 Mbps = 10^6 bit/s），不能按 2^20 计算。
      base_bdp = ceil((min_bw * 1000 * 1000 / 8) * rtt / 1000)
      if (base_bdp < 16384) base_bdp = 16384

      mem_bytes = mem * 1024 * 1024
      if (platform == "openwrt") {
        if (mem <= 128) mem_cap = 4 * 1024 * 1024
        else if (mem <= 256) mem_cap = 8 * 1024 * 1024
        else if (mem <= 512) mem_cap = 16 * 1024 * 1024
        else if (mem <= 1024) mem_cap = 32 * 1024 * 1024
        else mem_cap = clamp(int(mem_bytes * 0.05), 4 * 1024 * 1024, 64 * 1024 * 1024)
        mem_class = "openwrt-guarded"
        max_ratio = mem_cap / mem_bytes
      } else if (mem <= 256) {
        max_ratio = 0.06
        mem_class = "low"
      } else if (mem <= 512) {
        max_ratio = 0.08
        mem_class = "small"
      } else if (mem <= 1024) {
        max_ratio = 0.10
        mem_class = "medium"
      } else if (mem <= 2048) {
        max_ratio = 0.12
        mem_class = "high"
      } else {
        max_ratio = 0.15
        mem_class = "large"
      }
      if (platform != "openwrt" && aggressive == 1 && mem > 512) max_ratio += 0.03
      mem_cap = int(mem_bytes * max_ratio)
      if (platform == "openwrt") mem_cap = clamp(mem_cap, 4 * 1024 * 1024, 64 * 1024 * 1024)
      else mem_cap = clamp(mem_cap, 4 * 1024 * 1024, 256 * 1024 * 1024)

      latency_factor = clamp(rtt / 40, 1, 5)
      ratio = local / peer
      if (ratio <= 0) ratio = 1
      high_latency = rtt > 120 ? 1 : 0

      if (objective == "throughput") {
        recv_mult = high_latency ? 6.0 : 5.0
        send_mult = high_latency ? 3.0 : 2.5
      } else if (objective == "startup") {
        recv_mult = high_latency ? 2.8 : 2.0
        send_mult = high_latency ? 1.2 : 0.9
      } else {
        recv_mult = high_latency ? 3.2 : 2.0
        send_mult = high_latency ? 1.5 : 1.0
      }

      if (high_latency) {
        bandwidth_factor = clamp(2 * sqrt(ratio) * latency_factor, 1.5, 5)
        effective_bw = local * bandwidth_factor
        if (effective_bw > 2 * peer) effective_bw = 2 * peer
        model_bdp = ceil((effective_bw * 1024 * 1024 / 8) * rtt / 1000)
      } else {
        model_bdp = base_bdp
      }

      if (mem <= 256) {
        recv_mult *= 0.65
        send_mult *= 0.65
      } else if (mem <= 512) {
        recv_mult *= 0.8
        send_mult *= 0.8
      } else if (mem > 2048 && aggressive == 1) {
        recv_mult *= 1.2
        send_mult *= 1.15
      }

      if (ramp < 0.1) ramp = 0.1
      if (ramp > 1) ramp = 1
      if (objective == "startup") {
        recv_mult *= 0.9 + ramp * 0.25
        send_mult *= 0.85 + ramp * 0.20
      } else {
        recv_mult *= ramp
        send_mult *= ramp
      }

      rmem = int(model_bdp * recv_mult)
      wmem = int(model_bdp * send_mult)
      rmem_floor = int(base_bdp / 4)
      if (rmem_floor < 262144) rmem_floor = 262144
      wmem_floor = int(base_bdp / 4)
      if (wmem_floor < 262144) wmem_floor = 262144
      rmem = clamp(rmem, rmem_floor, mem_cap)
      wmem = clamp(wmem, wmem_floor, mem_cap)

      if (objective == "startup") {
        notsent = clamp(int(model_bdp / 32), 16384, 131072)
      } else if (objective == "retrans") {
        notsent = clamp(int(model_bdp / 16 * ramp), 32768, 524288)
      } else {
        notsent = clamp(int(model_bdp / 16), 16384, 524288)
      }
      adv = int(clamp(ceil(latency_factor * (objective == "throughput" ? 1.4 : 1.0)), 2, 8))
      backlog = int(clamp(8192 + model_bdp / 65536 * latency_factor, 8192, mem <= 512 ? 16384 : 32768))
      somaxconn = int(clamp(backlog * 0.5, 2560, mem <= 512 ? 8192 : 16384))
      synbacklog = int(clamp(backlog * 1.5, 8192, mem <= 512 ? 32768 : 65536))
      optmem = int(clamp(model_bdp / 32, 81920, 262144))

      printf "%d %d %d %d %d %d %d %d %s %d\n", rmem, wmem, adv, notsent, backlog, somaxconn, synbacklog, optmem, mem_class, base_bdp
    }
  '
}

print_recommendation() {
  local_mbps="$1"
  peer_mbps="$2"
  rtt_ms="$3"
  memory_mb_value="$4"
  objective="$5"
  ramp_rate="${6:-0.79}"
  aggressive="${7:-0}"

  values="$(recommend_values "$local_mbps" "$peer_mbps" "$rtt_ms" "$memory_mb_value" "$objective" "$ramp_rate" "$aggressive")"
  case "$values" in
    ERR*) die "$values" ;;
  esac
  # shellcheck disable=SC2086
  set -- $values
  rmem="$1"
  wmem="$2"
  adv="$3"
  notsent="$4"
  backlog="$5"
  somaxconn="$6"
  synbacklog="$7"
  optmem="$8"
  mem_class="$9"
  shift 9
  base_bdp="$1"

  echo "智能推荐结果："
  echo "  目标：$objective"
  echo "  基础 BDP：$base_bdp bytes"
  echo "  内存档位：$mem_class (${memory_mb_value}MiB)"
  echo "  net.core.rmem_max = $rmem"
  echo "  net.core.wmem_max = $wmem"
  echo "  net.ipv4.tcp_rmem = 4096 87380 $rmem"
  echo "  net.ipv4.tcp_wmem = 4096 65536 $wmem"
  echo "  net.ipv4.tcp_adv_win_scale = $adv"
  echo "  net.ipv4.tcp_notsent_lowat = $notsent"
  echo "  net.core.netdev_max_backlog = $backlog"
  echo "  net.core.somaxconn = $somaxconn"
  echo "  net.ipv4.tcp_max_syn_backlog = $synbacklog"
  echo "  net.core.optmem_max = $optmem"
}

recommend_preset_name() {
  rtt_ms="${1:-0}"
  memory_mb_value="${2:-1024}"
  retransmits="${3:-0}"
  download_bps="${4:-0}"
  if [ "$rtt_ms" -lt 30 ]; then
    index=1
  elif [ "$rtt_ms" -lt 70 ]; then
    index=2
  elif [ "$rtt_ms" -lt 130 ]; then
    index=3
  elif [ "$rtt_ms" -lt 190 ]; then
    index=4
  else
    index=5
  fi
  if [ "$memory_mb_value" -lt 256 ] && [ "$index" -gt 3 ]; then
    index=3
  fi
  if [ "$retransmits" -gt 500 ] && [ "$index" -gt 1 ]; then
    index=$((index - 1))
  fi
  if awk -v bps="$download_bps" 'BEGIN { exit !(bps > 0 && bps < 20000000) }' && [ "$index" -gt 3 ]; then
    index=3
  fi
  preset_by_number "$index"
}

recommend_preset_reason() {
  rtt_ms="${1:-0}"
  memory_mb_value="${2:-1024}"
  retransmits="${3:-0}"
  download_bps="${4:-0}"
  reason="RTT ${rtt_ms}ms / 内存 ${memory_mb_value}MiB / 重传 $(format_count "$retransmits") 次"
  if [ "$memory_mb_value" -lt 256 ]; then
    reason="$reason；低内存设备不推荐高挡位"
  fi
  if [ "$retransmits" -gt 500 ]; then
    reason="$reason；重传偏高，已降低推荐挡位"
  fi
  if awk -v bps="$download_bps" 'BEGIN { exit !(bps > 0 && bps < 20000000) }'; then
    reason="$reason；吞吐较低，可能是链路或限速问题"
  fi
  echo "$reason"
}

profile_probe_metrics() {
  host="$1"
  port="$2"
  bind_ip="$3"
  rtt_ms="$(detect_rtt_ms "$host")"
  upload_json="$(run_iperf_client "$host" "$port" 0 8 "$bind_ip" 2>/dev/null || true)"
  download_json="$(run_iperf_client "$host" "$port" 1 8 "$bind_ip" 2>/dev/null || true)"
  if ! printf '%s' "$upload_json" | grep -q '"end"'; then
    die "预制参数检测失败：上传 iperf3 未返回有效结果，请先确认服务端测速端口可达。"
  fi
  if ! printf '%s' "$download_json" | grep -q '"end"'; then
    die "预制参数检测失败：下载 iperf3 未返回有效结果，请先确认服务端测速端口可达。"
  fi
  upload_bps="$(printf '%s\n' "$upload_json" | extract_bps 2>/dev/null || true)"
  upload_retr="$(printf '%s\n' "$upload_json" | extract_retransmits 2>/dev/null || true)"
  upload_first="$(printf '%s\n' "$upload_json" | extract_first_interval_bps 2>/dev/null || true)"
  download_bps="$(printf '%s\n' "$download_json" | extract_bps 2>/dev/null || true)"
  download_retr="$(printf '%s\n' "$download_json" | extract_retransmits 2>/dev/null || true)"
  download_first="$(printf '%s\n' "$download_json" | extract_first_interval_bps 2>/dev/null || true)"
  for metric in "$upload_bps" "$upload_retr" "$upload_first" "$download_bps" "$download_retr" "$download_first"; do
    is_unsigned_integer "$metric" || die "预制参数检测失败：iperf3 JSON 缺少必要指标，未使用 0 代替。"
  done
  total_retr=$((upload_retr + download_retr))
  memory_mb_value="$(memory_mb)"
  recommended="$(recommend_preset_name "$rtt_ms" "$memory_mb_value" "$total_retr" "$download_bps")"
  cat <<EOF
$rtt_ms $memory_mb_value $upload_bps $upload_retr $upload_first $download_bps $download_retr $download_first $total_retr $recommended
EOF
}

# END src/tuning/profiles.sh

# BEGIN src/tuning/optimizer.sh
# Module: src/tuning/optimizer.sh
# 中断/异常退出时回滚"已写入但未复测"的参数，兑现"仅保留经过复测的调整"承诺。
tune_abort_cleanup() {
  [ "${PENDING_UNVERIFIED_TUNE:-0}" = "1" ] || return 0
  PENDING_UNVERIFIED_TUNE=0
  warn "会话中断：正在回滚尚未复测的参数写入。"
  rollback_last >/dev/null 2>&1 || true
}

current_max_buffers() {
  rmem="$(sysctl -n net.core.rmem_max 2>/dev/null || echo 67108864)"
  wmem="$(sysctl -n net.core.wmem_max 2>/dev/null || echo 67108864)"
  echo "$rmem $wmem"
}

tune_step() {
  objective="$1"
  retr="$2"
  bps="$3"
  target_retr="$4"
  local_mbps="$5"
  peer_mbps="$6"
  rtt_ms="$7"
  memory_mb_value="$8"
  ramp_rate="${9:-0.79}"
  aggressive="0"
  if [ "$#" -ge 10 ]; then
    shift 9
    aggressive="${1:-0}"
  fi

  cap="$(memory_cap_bytes "$memory_mb_value" "$aggressive")"
  bdp_bytes="$(awk -v bw="$peer_mbps" -v rtt="$rtt_ms" 'BEGIN {b=bw*1024*1024/8*rtt/1000; if(b<32768) b=32768; printf "%d", b}')"

  cur_rmem="$(sysctl -n net.core.rmem_max 2>/dev/null || echo 4194304)"
  cur_wmem="$(sysctl -n net.core.wmem_max 2>/dev/null || echo 4194304)"
  cur_notsent="$(sysctl -n net.ipv4.tcp_notsent_lowat 2>/dev/null || echo 131072)"
  cur_adv="$(sysctl -n net.ipv4.tcp_adv_win_scale 2>/dev/null || echo 2)"
  is_unsigned_integer "$cur_rmem" || cur_rmem=4194304
  is_unsigned_integer "$cur_wmem" || cur_wmem=4194304
  is_unsigned_integer "$cur_notsent" || cur_notsent=131072
  is_integer "$cur_adv" || cur_adv=2

  values="$(recommend_values "$local_mbps" "$peer_mbps" "$rtt_ms" "$memory_mb_value" "$objective" "$ramp_rate" "$aggressive")"
  case "$values" in
    ERR*) die "$values" ;;
  esac
  # shellcheck disable=SC2086
  set -- $values
  rmem="$1"; wmem="$2"; adv="$3"; notsent="$4"
  backlog="$5"; somaxconn="$6"; synbacklog="$7"; optmem="$8"
  is_unsigned_integer "$backlog" || backlog=16384
  is_unsigned_integer "$somaxconn" || somaxconn=8192
  is_unsigned_integer "$synbacklog" || synbacklog=32768
  is_unsigned_integer "$optmem" || optmem=81920

  rmem="$cur_rmem"
  wmem="$cur_wmem"
  notsent="$cur_notsent"
  adv="$cur_adv"

  min_rmem=$((bdp_bytes / 2))
  min_wmem=$((bdp_bytes / 4))
  [ "$min_rmem" -lt 65536 ] && min_rmem=65536
  [ "$min_wmem" -lt 65536 ] && min_wmem=65536

  case "$objective" in
    retrans)
      if [ "$retr" -gt "$target_retr" ]; then
        notsent="$(awk -v n="$notsent" 'BEGIN {v=int(n*0.80); if(v<16384) v=16384; printf "%d", v}')"
        if [ "$retr" -gt 2000 ]; then
          rmem="$(awk -v r="$rmem" 'BEGIN {v=int(r*0.95); if(v<65536) v=65536; printf "%d", v}')"
          wmem="$(awk -v w="$wmem" 'BEGIN {v=int(w*0.95); if(v<65536) v=65536; printf "%d", v}')"
        fi
      fi
      ;;
    throughput)
      if [ "$bps" != "0" ]; then
        rmem="$(awk -v r="$rmem" -v b="$bdp_bytes" 'BEGIN {v=int(r*1.35); if(v<b*4) v=int(b*4); printf "%d", v}')"
        wmem="$(awk -v w="$wmem" -v b="$bdp_bytes" 'BEGIN {v=int(w*1.35); if(v<b*4) v=int(b*4); printf "%d", v}')"
        notsent="$(awk -v n="$notsent" 'BEGIN {v=int(n*1.25); if(v>524288) v=524288; printf "%d", v}')"
        if [ "$adv" -gt 1 ]; then
          adv="$(awk -v a="$adv" 'BEGIN {v=a-1; if(v<1) v=1; printf "%d", v}')"
        fi
      fi
      ;;
    startup)
      notsent="$(awk -v n="$notsent" 'BEGIN {
        if (n > 65536) v=int(n*0.75); else v=int(n*0.90)
        if (v < 16384) v=16384
        if (v > 65536) v=65536
        printf "%d", v
      }')"
      wmem="$(awk -v w="$wmem" -v min="$min_wmem" 'BEGIN {v=w; if(v<min) v=min; printf "%d", v}')"
      rmem="$(awk -v r="$rmem" -v min="$min_rmem" 'BEGIN {v=r; if(v<min) v=min; printf "%d", v}')"
      adv="$(awk -v a="$adv" 'BEGIN {v=a; if(v<2) v=2; if(v>3) v=3; printf "%d", v}')"
      ;;
  esac

  [ "$rmem" -lt "$min_rmem" ] && rmem="$min_rmem"
  [ "$wmem" -lt "$min_wmem" ] && wmem="$min_wmem"
  [ "$rmem" -gt "$cap" ] && rmem="$cap"
  [ "$wmem" -gt "$cap" ] && wmem="$cap"

  echo "$rmem $wmem $adv $notsent $backlog $somaxconn $synbacklog $optmem"
}


auto_tune() {
  host="$1"
  port="$2"
  objective="$3"
  target_retr="$4"
  rounds="$5"
  reverse="${6:-1}"
  local_mbps="${7:-0}"
  peer_mbps="${8:-0}"
  rtt_ms="${9:-100}"
  memory_mb_value=""
  ramp_rate="0.79"
  aggressive="0"
  allow_same_public="0"
  machine_role="endpoint"
  critical_direction="download"
  protocol_class="unknown"
  proxy_software=""
  traffic_path=""
  if [ "$#" -ge 10 ]; then
    shift 9
    memory_mb_value="${1:-}"
    [ "$#" -ge 2 ] && ramp_rate="${2:-0.79}"
    [ "$#" -ge 3 ] && aggressive="${3:-0}"
    [ "$#" -ge 4 ] && allow_same_public="${4:-0}"
    [ "$#" -ge 5 ] && machine_role="${5:-endpoint}"
    [ "$#" -ge 6 ] && critical_direction="${6:-download}"
    [ "$#" -ge 7 ] && protocol_class="${7:-unknown}"
    [ "$#" -ge 8 ] && proxy_software="${8:-}"
    [ "$#" -ge 9 ] && traffic_path="${9:-}"
  fi

  case "$objective" in
    retrans|throughput|startup) ;;
    *) die "--objective 只支持 retrans、throughput、startup" ;;
  esac
  context_line="$(normalize_link_context "$machine_role" "$critical_direction" "$protocol_class" "$proxy_software" "$traffic_path")"
  machine_role="$(printf '%s\n' "$context_line" | cut -f1)"
  critical_direction="$(printf '%s\n' "$context_line" | cut -f2)"
  protocol_class="$(printf '%s\n' "$context_line" | cut -f3)"
  proxy_software="$(printf '%s\n' "$context_line" | cut -f4)"
  traffic_path="$(printf '%s\n' "$context_line" | cut -f5)"
  if [ "$protocol_class" = "udp-quic" ]; then
    die "protocol-class=udp-quic 时不默认执行 TCP buffer 写入；请先运行 advanced-diagnose 获取 PMTU/qdisc/P1/P4 证据。"
  fi
  need_root
  install_runtime_deps
  detect_os
  [ "$OS_FAMILY" != "macos" ] || macos_write_unsupported
  ensure_tcp_baseline
  auto_initial_backup="$(manual_backup_begin "auto-$objective" 2>/dev/null || true)"
  [ -n "$memory_mb_value" ] || memory_mb_value="$(memory_mb)"
  local_public_ip="$(public_ip || true)"
  if [ "$allow_same_public" != "1" ] && [ -n "$local_public_ip" ] && [ "$host" = "$local_public_ip" ]; then
    warn "对端地址 $host 与本机公网出口 $local_public_ip 相同，可能是代理出口/NAT hairpin；已按真实链路继续测试。"
  fi

  bind_ip="$(local_lan_ipv4 || true)"
  case "$host" in
    127.*|localhost|"$bind_ip") bind_ip="" ;;
  esac
  route_iface="$(route_iface_for_host "$host")"
  route_mtu="$(iface_mtu "$route_iface")"
  route_pmtu="$(probe_pmtu "$host")"
  qdisc_before="$(qdisc_stats "$route_iface")"
  mode_name="$(objective_label "$objective")"
  transfer_name="$(direction_label "$reverse")"
  display_local_ip="${bind_ip:-$(local_lan_ipv4 || true)}"
  [ -n "$display_local_ip" ] || display_local_ip="未识别"
  TUNE_SIMPLE_OUTPUT=1

  clear_screen
  print_header "正在优化 · $mode_name"
  ui_subtitle "$transfer_name · 本机 $display_local_ip · 第 1/$rounds 轮"
  post_client_stage "auto" "running" "$mode_name"
  echo
  ui_section "优化概览"
  ui_row "模式" "$mode_name"
  ui_row "方向" "$transfer_name"
  ui_row "机器角色" "$machine_role"
  ui_row "协议类型" "$protocol_class"
  ui_row "本机地址" "$display_local_ip"
  ui_row "测速节点" "已连接的服务端"
  ui_row "PMTU/接口" "$route_pmtu / $route_iface mtu=$route_mtu"
  ui_row "最大轮数" "$rounds"
  echo
  ui_note "说明" "测速使用本机局域网地址作为源地址，远端连接地址不会显示在界面中。"

  i=1
  previous_retr=""
  previous_bps=""
  previous_startup_bps=""
  first_retr=""
  first_bps=""
  first_startup_bps=""
  final_retr="0"
  final_bps="0"
  final_startup_bps="0"
  best_bps="0"
  applied_change_count="0"
  rolled_back_regression="0"
  completed_rounds="0"
  previous_rtt=""
  previous_qdisc="$qdisc_before"
  OBJECTIVE_GUARD_OK=1
  while [ "$i" -le "$rounds" ]; do
    echo
    ui_section "第 $i/$rounds 轮测试"
    progress_steps "$i" "$rounds"
    ui_note "状态" "正在执行 $TCP_TUNE_SAMPLE_COUNT 次 iperf3 测试并计算中位数..."
    sample_rc=0
    sample_metrics="$(measure_iperf_samples "$host" "$port" "$reverse" 20 "$bind_ip" 1 "$TCP_TUNE_SAMPLE_COUNT")" || sample_rc="$?"
    if [ "$sample_rc" != "0" ]; then
      if [ "$applied_change_count" -gt 0 ]; then
        rollback_last >/dev/null 2>&1 || true
        PENDING_UNVERIFIED_TUNE=0
      fi
      if [ "$sample_rc" = "2" ]; then
        DIE_EXIT_CODE="$EXIT_BENCHMARK" die "测速离散度超过 ${TCP_TUNE_MAX_SPREAD_PERCENT}%，结果不稳定，已回滚本轮参数。"
      fi
      DIE_EXIT_CODE="$EXIT_BENCHMARK" die "iperf3 多样本测速失败或关键指标未检测，已回滚本轮参数。"
    fi
    tab="$(printf '\t')"
    old_ifs="$IFS"; IFS="$tab"
    read -r bps retr startup_bps sample_spread <<EOF
$sample_metrics
EOF
    IFS="$old_ifs"
    current_rtt="$(detect_rtt_ms "$host")"
    current_qdisc="$(qdisc_stats "$route_iface")"
    guard_delta="$(qdisc_delta "$previous_qdisc" "$current_qdisc")"
    old_ifs="$IFS"; IFS=' '
    read -r guard_drop guard_backlog <<EOF
$guard_delta
EOF
    IFS="$old_ifs"
    OBJECTIVE_GUARD_OK=1
    if is_unsigned_integer "$previous_rtt" && is_unsigned_integer "$current_rtt"; then
      if awk -v before="$previous_rtt" -v after="$current_rtt" 'BEGIN {exit !(before > 0 && after > before * 1.15 && after - before > 5)}'; then
        OBJECTIVE_GUARD_OK=0
      fi
    fi
    if is_unsigned_integer "$guard_drop" && [ "$guard_drop" -gt 10 ]; then OBJECTIVE_GUARD_OK=0; fi
    if is_unsigned_integer "$guard_backlog" && [ "$guard_backlog" -gt 65536 ]; then OBJECTIVE_GUARD_OK=0; fi
    if [ "$bps" = "0" ] && [ "$i" = "1" ]; then
      DIE_EXIT_CODE="$EXIT_BENCHMARK" die "iperf3 中位速率为 0，请检查网络连通性。"
    fi
    final_retr="$retr"
    final_bps="$bps"
    final_startup_bps="$startup_bps"
    completed_rounds="$i"
    [ -n "$first_retr" ] || first_retr="$retr"
    [ -n "$first_bps" ] || first_bps="$bps"
    [ -n "$first_startup_bps" ] || first_startup_bps="$startup_bps"
    if awk -v current="$bps" -v best="$best_bps" 'BEGIN { exit !(current > best) }'; then
      best_bps="$bps"
    fi
    readable_rate="$(format_rate "$bps")"
    readable_retr="$(format_count "$retr")"
    previous_rate="无"
    [ -n "$previous_bps" ] && previous_rate="$(format_rate "$previous_bps")"
    previous_retr_text="无"
    [ -n "$previous_retr" ] && previous_retr_text="$(format_count "$previous_retr") 次"
    retr_delta="$(percent_delta "$first_retr" "$retr")"
    if [ "$retr" -le "$target_retr" ]; then
      retr_state="good"
    else
      retr_state="bad"
    fi
    trend="$(trend_label "$retr" "$previous_retr")"
    action="$(next_action_label "$objective" "$retr" "$target_retr")"
    case "$trend" in
      重传下降|建立基线|保持稳定) trend_state="good" ;;
      *) trend_state="warn" ;;
    esac
    metric_line "当前速度" "$readable_rate（上轮 $previous_rate）" "info"
    metric_line "当前重传" "$readable_retr 次（上轮 $previous_retr_text）" "$retr_state"
    metric_line "改善幅度" "$retr_delta · $trend" "$trend_state"
    metric_line "当前动作" "$action" "warn"
    metric_line "样本离散" "${sample_spread}%" "info"
    metric_line "RTT" "${current_rtt:-unknown}ms" "info"
    metric_line "qdisc 增量" "drop=${guard_drop:-unknown} backlog=${guard_backlog:-unknown}" "info"
    if [ "$objective" = "startup" ]; then
      metric_line "首秒速度" "$(format_rate "$startup_bps")" "warn"
    fi
    if [ -n "${TUNE_REPORT_PEER:-}" ] && [ -n "${TUNE_REPORT_TOKEN:-}" ]; then
      report_direction="download"
      [ "$reverse" = "0" ] && report_direction="upload"
      report_data="{\"role\":\"client-result\",\"lan_ip\":$(json_string "${TUNE_CLIENT_IP:-$display_local_ip}"),\"round\":$i,\"rounds\":$rounds,\"objective\":$(json_string "$objective"),\"direction\":$(json_string "$report_direction"),\"retransmits\":$retr,\"bits_per_second\":$bps,\"first_second_bits_per_second\":$startup_bps,\"time\":$(date +%s)}"
      post_json "$TUNE_REPORT_PEER/report" "$TUNE_REPORT_TOKEN" "$report_data" >/dev/null 2>&1 || true
    fi

    if [ "$applied_change_count" -gt 0 ] && [ -n "$previous_retr" ]; then
      PENDING_UNVERIFIED_TUNE=0
      if objective_step_improved "$objective" "$previous_bps" "$bps" "$previous_retr" "$retr" "$previous_startup_bps" "$startup_bps" "$target_retr"; then
        ui_note "验证" "上一轮写入已让目标指标改善，保留本轮参数。"
      else
        warn "上一轮写入没有让目标指标改善，正在撤销这次参数调整。"
        rollback_last
        applied_change_count=$((applied_change_count - 1))
        rolled_back_regression="1"
        final_retr="$previous_retr"
        final_bps="$previous_bps"
        final_startup_bps="$previous_startup_bps"
        break
      fi
    fi

    regressed="0"
    if [ "$applied_change_count" -gt 0 ] && [ -n "$previous_retr" ]; then
      case "$objective" in
        retrans)
          if awk -v current="$retr" -v previous="$previous_retr" 'BEGIN { exit !(previous > 0 && current > previous * 1.50) }'; then
            regressed="1"
          fi
          ;;
        throughput)
          if awk -v current="$bps" -v previous="$previous_bps" 'BEGIN { exit !(previous > 0 && current < previous * 0.80) }'; then
            regressed="1"
          fi
          ;;
        startup)
          if awk -v current="$startup_bps" -v previous="$previous_startup_bps" 'BEGIN { exit !(previous > 0 && current < previous * 0.75) }'; then
            regressed="1"
          fi
          if awk -v current="$retr" -v previous="$previous_retr" 'BEGIN { exit !(previous > 100 && current > previous * 3.0 && current > 500) }'; then
            regressed="1"
          fi
          ;;
      esac
    fi
    if [ "$regressed" = "1" ]; then
      consecutive_regression="${consecutive_regression:-0}"
      consecutive_regression=$((consecutive_regression + 1))
      if [ "$consecutive_regression" -ge 2 ]; then
        warn "连续 2 轮退化，正在回滚最新参数调整。"
        rollback_last
        applied_change_count=$((applied_change_count - 1))
        rolled_back_regression="1"
        final_retr="$previous_retr"
        final_bps="$previous_bps"
        final_startup_bps="$previous_startup_bps"
        break
      else
        warn "本轮表现波动，暂不回滚，下一轮继续观察。"
      fi
    else
      consecutive_regression="0"
    fi

    measured_mbps="$(awk -v bps="$bps" 'BEGIN {v=bps/1000000; if (v < 1) v=1; printf "%d\n", v}')"
    [ "$peer_mbps" = "0" ] && peer_mbps="$measured_mbps"
    [ "$local_mbps" = "0" ] && local_mbps="$peer_mbps"

    if [ "$objective" = "retrans" ] && [ "$bps" != "0" ]; then
      retrans_target_met="0"
      if [ "$retr" -le "$target_retr" ]; then
        retrans_target_met="1"
      fi
      if [ -n "$first_retr" ] && [ "$first_retr" -gt 0 ]; then
        if awk -v r="$retr" -v fir="$first_retr" 'BEGIN { exit !(r < fir * 0.50 && r < 500) }'; then
          retrans_target_met="1"
        fi
      fi
      if [ "$retrans_target_met" = "1" ]; then
        echo
        if [ "$applied_change_count" -gt 0 ]; then
          ui_note "结果" "目标已达成，进入结果页。"
        else
          ui_note "结果" "基线已达到重传目标，不写入额外参数。"
        fi
        break
      fi
    fi
    if [ "$i" -ge "$rounds" ]; then
      echo
      if [ "$applied_change_count" -gt 0 ]; then
        ui_note "结果" "已达到最大轮数，保留最后一次已复测通过的参数。"
      else
        ui_note "结果" "已完成基线测试，本轮没有写入参数。"
      fi
      break
    fi

    step_values="$(tune_step "$objective" "$retr" "$bps" "$target_retr" "$local_mbps" "$peer_mbps" "$rtt_ms" "$memory_mb_value" "$ramp_rate" "$aggressive")"
    old_ifs="$IFS"; IFS=' '
    read -r step_rmem step_wmem step_adv step_notsent step_backlog step_somax step_syn step_optmem <<EOF
$step_values
EOF
    IFS="$old_ifs"
    apply_buffers "$step_rmem" "$step_wmem" "$step_adv" "$step_notsent" "$step_backlog" "$step_somax" "$step_syn" "$step_optmem"
    applied_change_count=$((applied_change_count + 1))
    # 本次写入要等下一轮复测通过才算保留；中断时由 tune_abort_cleanup 回滚。
    PENDING_UNVERIFIED_TUNE=1
    if [ "$objective" = "retrans" ] && [ "$retr" -gt "$target_retr" ]; then
      ramp_rate="$(awk -v r="$ramp_rate" -v retr="$retr" -v target="$target_retr" 'BEGIN {
        factor = 0.92
        if (retr > target + 20) factor = 0.78
        else if (retr > target + 5) factor = 0.85
        v = r * factor
        if (v < 0.35) v = 0.35
        printf "%.3f\n", v
      }')"
    elif [ "$objective" = "throughput" ]; then
      ramp_rate="$(awk -v r="$ramp_rate" -v retr="$retr" -v target="$target_retr" 'BEGIN {
        if (retr <= target) v = r * 1.15
        else v = r * 0.90
        if (v > 1.20) v = 1.20
        if (v < 0.45) v = 0.45
        printf "%.3f\n", v
      }')"
    fi
    previous_retr="$retr"
    previous_bps="$bps"
    previous_startup_bps="$startup_bps"
    previous_rtt="$current_rtt"
    previous_qdisc="$current_qdisc"
    i=$((i + 1))
  done
  [ "$completed_rounds" = "0" ] && completed_rounds="$rounds"
  if [ "$applied_change_count" -gt 0 ] && [ -n "${auto_initial_backup:-}" ]; then
    if objective_numbers_regressed "$objective" "${first_bps:-0}" "$final_bps" "${first_retr:-0}" "$final_retr" "${first_startup_bps:-0}" "$final_startup_bps" "$target_retr"; then
      restore_manual_backup "$auto_initial_backup" >/dev/null 2>&1 || true
      rolled_back_regression="1"
      applied_change_count="0"
      final_retr="${first_retr:-0}"
      final_bps="${first_bps:-0}"
      final_startup_bps="${first_startup_bps:-0}"
    fi
  fi
  if [ "$applied_change_count" -gt 0 ] && [ -n "${auto_initial_backup:-}" ]; then
    if ! objective_run_succeeded "$objective" "${first_bps:-0}" "$final_bps" "${first_retr:-0}" "$final_retr" "${first_startup_bps:-0}" "$final_startup_bps" "$target_retr"; then
      restore_manual_backup "$auto_initial_backup" >/dev/null 2>&1 || true
      rolled_back_regression="1"
      applied_change_count="0"
      final_retr="${first_retr:-0}"
      final_bps="${first_bps:-0}"
      final_startup_bps="${first_startup_bps:-0}"
    fi
  fi
  qdisc_after="$(qdisc_stats "$route_iface")"
  qdisc_delta_values="$(qdisc_delta "$qdisc_before" "$qdisc_after")"
  # shellcheck disable=SC2086
  set -- $qdisc_delta_values
  qdisc_drop_delta="${1:-unknown}"
  qdisc_backlog_delta="${2:-unknown}"
  if [ "$rolled_back_regression" = "1" ]; then
    post_client_stage "auto" "rollback" "$mode_name"
  else
    post_client_stage "auto" "success" "$mode_name"
  fi
  clear_screen
  print_header "优化完成"
  ui_subtitle "$mode_name · $transfer_name · 共测试 $completed_rounds 轮"
  echo
  ui_section "结论"
  final_rate="$(format_rate "$final_bps")"
  final_retr_text="$(format_count "$final_retr")"
  first_rate="$(format_rate "${first_bps:-0}")"
  first_startup_rate="$(format_rate "${first_startup_bps:-0}")"
  final_startup_rate="$(format_rate "$final_startup_bps")"
  best_rate="$(format_rate "$best_bps")"
  first_retr_text="$(format_count "${first_retr:-0}")"
  speed_delta="$(percent_delta "${first_bps:-0}" "$final_bps")"
  retr_delta="$(percent_delta "${first_retr:-0}" "$final_retr")"
  case "$objective" in
    throughput)
      ui_row "结论" "吞吐测试完成，最高速度 $best_rate，末轮重传 $final_retr_text 次。"
      ;;
    startup)
      ui_row "结论" "起速测试完成，末轮首秒速度 $final_startup_rate。"
      ;;
    *)
      retr_significantly_reduced="0"
      if [ -n "${first_retr:-}" ] && [ "${first_retr:-0}" -gt 0 ]; then
        if awk -v r="$final_retr" -v fir="$first_retr" 'BEGIN { exit !(r < fir * 0.50) }'; then
          retr_significantly_reduced="1"
        fi
      fi
      if [ "$final_retr" -le "$target_retr" ] || [ "$retr_significantly_reduced" = "1" ]; then
        ui_row "结论" "重传已显著改善，保持当前配置。"
      else
        warn "已完成 $completed_rounds 轮，重传尚未降至目标值。"
        ui_row "结论" "重传尚未达到目标，建议检查链路质量后再试。"
      fi
      ;;
  esac
  echo
  ui_section "优化前后"
  printf "  %s%s │ %-14s │ %-14s │ %-10s%s\n" "$COLOR_BOLD$COLOR_CYAN" "$(ui_pad "指标" 12)" "优化前" "优化后" "变化" "$COLOR_RESET"
  printf "  %s─────────────┼────────────────┼────────────────┼──────────%s\n" "$COLOR_DIM" "$COLOR_RESET"
  printf "  %s │ %-14s │ %-14s │ %-10s\n" "$(ui_pad "传输速度" 12)" "$first_rate" "$final_rate" "$speed_delta"
  printf "  %s │ %-14s │ %-14s │ %-10s\n" "$(ui_pad "重传次数" 12)" "$first_retr_text" "$final_retr_text" "$retr_delta"
  if [ "$objective" = "startup" ]; then
    startup_delta="$(percent_delta "${first_startup_bps:-0}" "$final_startup_bps")"
    printf "  %s │ %-14s │ %-14s │ %-10s\n" "$(ui_pad "首秒速度" 12)" "$first_startup_rate" "$final_startup_rate" "$startup_delta"
  fi
  echo
  ui_section "配置摘要"
  ui_note "qdisc delta" "drop=$qdisc_drop_delta backlog=$qdisc_backlog_delta"
  if [ "$final_retr" -gt "$target_retr" ] && [ "$qdisc_drop_delta" = "0" ] && [ "$qdisc_backlog_delta" = "0" ]; then
    ui_note "诊断" "重传仍高但本机 qdisc 无 drop/backlog 增量，更可能是路径、对端或上游拥塞。"
  fi
  if [ "$rolled_back_regression" = "1" ] && [ "$applied_change_count" -eq 0 ]; then
    ui_note "已回退" "最新调整表现退化，已恢复优化前配置。"
    ui_note "回滚" "没有保留本次参数修改。"
  elif [ "$rolled_back_regression" = "1" ]; then
    ui_note "已回退" "已撤销最新退化调整，保留前一轮更优配置。"
    ui_note "回滚" "保留的调整仍可通过 rollback 命令恢复。"
  elif [ "$applied_change_count" -gt 0 ]; then
    ui_note "已保存" "仅保留经过下一轮复测的参数调整。"
    ui_note "回滚" "已创建备份，可在客户端菜单或 rollback 命令中恢复。"
    params_text="rmem=$(sysctl -n net.core.rmem_max 2>/dev/null || echo unknown) wmem=$(sysctl -n net.core.wmem_max 2>/dev/null || echo unknown) notsent=$(sysctl -n net.ipv4.tcp_notsent_lowat 2>/dev/null || echo unknown) limit=$(sysctl -n net.ipv4.tcp_limit_output_bytes 2>/dev/null || echo unknown)"
    report_path="$(write_tuning_profile "$mode_name" "$machine_role" "$critical_direction" "$protocol_class" "$host" "$transfer_name $(format_rate "$final_bps") retr=$final_retr first=$(format_rate "$final_startup_bps")" "not-run" "$route_pmtu" "drop=$qdisc_drop_delta backlog=$qdisc_backlog_delta" "$params_text" "$auto_initial_backup" "目标指标通过复测，保留本轮参数。")"
    ui_note "报告" "$report_path"
  else
    ui_note "未修改" "本次只完成基线测试，没有保存未经复测的参数。"
    ui_note "回滚" "本轮未创建新的参数修改。"
  fi
  echo
  ui_section "下一步操作"
  ui_menu_item "1" "返回客户端主页" "回到操作菜单"
  ui_menu_item "2" "换一种模式继续" "重新选择优化目标"
  ui_menu_item "3" "查看详细参数" "检查当前 TCP 配置"
  ui_menu_item "4" "回滚本次修改" "恢复优化前的系统参数" "$COLOR_YELLOW"
}

# END src/tuning/optimizer.sh

# BEGIN src/tuning/diagnostics.sh
# Module: src/tuning/diagnostics.sh
status_short() {
  echo "当前关键参数："
  sysctl net.ipv4.tcp_congestion_control 2>/dev/null || true
  sysctl net.core.default_qdisc 2>/dev/null || true
  sysctl net.ipv4.tcp_rmem 2>/dev/null || true
  sysctl net.ipv4.tcp_wmem 2>/dev/null || true
  sysctl net.core.rmem_max 2>/dev/null || true
  sysctl net.core.wmem_max 2>/dev/null || true
  sysctl net.ipv4.tcp_notsent_lowat 2>/dev/null || true
  sysctl net.ipv4.tcp_limit_output_bytes 2>/dev/null || true
  sysctl net.ipv4.tcp_autocorking 2>/dev/null || true
}

status_full() {
  detect_os
  if [ "${OUTPUT_MODE:-human}" = "json" ]; then
    cc="$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || true)"
    qdisc="$(sysctl -n net.core.default_qdisc 2>/dev/null || true)"
    rmem="$(sysctl -n net.core.rmem_max 2>/dev/null || true)"
    wmem="$(sysctl -n net.core.wmem_max 2>/dev/null || true)"
    data="{\"app_version\":$(json_string "$APP_VERSION"),\"os\":$(json_string "$OS_NAME"),\"platform\":$(json_string "$OS_FAMILY"),\"congestion_control\":$(if [ -n "$cc" ]; then json_string "$cc"; else printf null; fi),\"qdisc\":$(if [ -n "$qdisc" ]; then json_string "$qdisc"; else printf null; fi),\"rmem_max\":$(if is_unsigned_integer "$rmem"; then printf '%s' "$rmem"; else printf null; fi),\"wmem_max\":$(if is_unsigned_integer "$wmem"; then printf '%s' "$wmem"; else printf null; fi)}"
    json_envelope true status "$data" '[]'
    return 0
  fi
  echo "$APP_NAME $APP_VERSION"
  echo "系统：$OS_NAME"
  echo "包管理器：$PKG_MANAGER"
  echo "内核：$(uname -a 2>/dev/null || echo unknown)"
  echo
  status_short
  echo
  echo "命令依赖："
  for cmd in iperf3 curl wget sysctl tc ip python3; do
    if have_cmd "$cmd"; then
      echo "  $cmd: $(command -v "$cmd")"
    else
      echo "  $cmd: 缺失"
    fi
  done
  echo
  openwrt_advice
}

openwrt_advice() {
  detect_os
  [ "$OS_FAMILY" = "openwrt" ] || return 0
  echo "OpenWrt 优化建议："
  if ! have_cmd iperf3; then
    echo "  - 建议安装 iperf3：opkg update && opkg install iperf3"
  fi
  if ! have_cmd curl; then
    echo "  - 建议安装 curl：opkg update && opkg install curl"
  fi
  if ! have_cmd tc; then
    echo "  - 如需自动调 cake/fq，建议安装：opkg install tc-full kmod-ifb kmod-sched-cake"
  fi
  mem_kb="$(awk '/MemTotal/ {print $2}' /proc/meminfo 2>/dev/null || echo 0)"
  if [ "$mem_kb" -gt 0 ] && [ "$mem_kb" -lt 262144 ]; then
    echo "  - 当前内存低于 256MiB，不建议直接使用高缓冲预设。"
  fi
}

detect_rtt_ms() {
  host="$1"
  have_cmd ping || { echo 0; return 0; }
  output="$(ping -c 3 -W 1 "$host" 2>/dev/null || true)"
  avg="$(printf '%s\n' "$output" | awk -F'=' '/rtt|round-trip/ { split($2,a,"/"); printf "%d\n", a[2] + 0; found=1 } END { if (!found) print 0 }' | tail -n 1)"
  is_unsigned_integer "$avg" || avg=0
  echo "$avg"
}

route_iface_for_host() {
  host="$1"
  have_cmd ip || { echo unsupported; return 0; }
  route_output="$(ip route get "$host" 2>/dev/null)" || { echo failed; return 0; }
  printf '%s\n' "$route_output" | awk '{
    for (i = 1; i <= NF; i++) {
      if ($i == "dev" && (i + 1) <= NF) {
        print $(i + 1)
        exit
      }
    }
  }' | awk 'NF {print; found=1; exit} END {if (!found) print "unknown"}'
}

iface_mtu() {
  iface="$1"
  case "$iface" in
    ""|unknown) echo unknown; return 0 ;;
    unsupported|failed) echo "$iface"; return 0 ;;
  esac
  if [ -r "/sys/class/net/$iface/mtu" ]; then
    cat "/sys/class/net/$iface/mtu" 2>/dev/null || echo failed
  else
    echo unsupported
  fi
}

qdisc_stats() {
  iface="$1"
  have_cmd tc || { echo "unsupported unsupported"; return 0; }
  case "$iface" in
    ""|unknown) echo "unknown unknown"; return 0 ;;
    unsupported) echo "unsupported unsupported"; return 0 ;;
    failed) echo "failed failed"; return 0 ;;
  esac
  qdisc_output="$(tc -s qdisc show dev "$iface" 2>/dev/null)" || { echo "failed failed"; return 0; }
  printf '%s\n' "$qdisc_output" | awk '
    BEGIN { drops = 0; backlog = 0; seen = 0 }
    {
      for (i = 1; i <= NF; i++) {
        token = $i
        gsub(/[(),]/, "", token)
        if (token == "dropped" && (i + 1) <= NF) {
          value = $(i + 1)
          gsub(/[^0-9]/, "", value)
          if (value != "") { drops += value + 0; seen = 1 }
        }
        if (token == "backlog" && (i + 1) <= NF) {
          value = $(i + 1)
          gsub(/[^0-9]/, "", value)
          if (value != "") { backlog += value + 0; seen = 1 }
        }
      }
    }
    END {
      if (seen) printf "%d %d\n", drops, backlog
      else print "unknown unknown"
    }
  '
}

qdisc_delta() {
  before="$1"
  after="$2"
  # shellcheck disable=SC2086
  set -- $before
  before_drop="${1:-unknown}"
  before_backlog="${2:-unknown}"
  # shellcheck disable=SC2086
  set -- $after
  after_drop="${1:-unknown}"
  after_backlog="${2:-unknown}"
  if is_unsigned_integer "$before_drop" && is_unsigned_integer "$after_drop"; then
    drop_delta=$((after_drop - before_drop))
    [ "$drop_delta" -lt 0 ] && drop_delta=0
  else
    case "$before_drop:$after_drop" in
      *failed*) drop_delta="failed" ;;
      *unsupported*) drop_delta="unsupported" ;;
      *) drop_delta="unknown" ;;
    esac
  fi
  if is_unsigned_integer "$before_backlog" && is_unsigned_integer "$after_backlog"; then
    backlog_delta=$((after_backlog - before_backlog))
    [ "$backlog_delta" -lt 0 ] && backlog_delta=0
  else
    case "$before_backlog:$after_backlog" in
      *failed*) backlog_delta="failed" ;;
      *unsupported*) backlog_delta="unsupported" ;;
      *) backlog_delta="unknown" ;;
    esac
  fi
  printf "%s %s\n" "$drop_delta" "$backlog_delta"
}

probe_pmtu() {
  host="$1"
  if have_cmd tracepath; then
    trace_output="$(tracepath -n -m 8 "$host" 2>/dev/null)" || { echo failed; return 0; }
    pmtu="$(printf '%s\n' "$trace_output" | awk '/pmtu/ {for (i=1;i<=NF;i++) if ($i=="pmtu" && (i+1)<=NF) print $(i+1)}' | tail -n 1)"
    if is_unsigned_integer "$pmtu"; then
      echo "$pmtu"
      return 0
    fi
  fi
  case "$host" in
    *:*) echo unsupported; return 0 ;;
  esac
  have_cmd ping || { echo unsupported; return 0; }
  for payload in 1472 1464 1452 1412 1372 1332 1292 1252 1212 1172; do
    if ping -c 1 -W 1 -M 'do' -s "$payload" "$host" >/dev/null 2>&1; then
      echo $((payload + 28))
      return 0
    fi
  done
  echo unknown
}

measure_iperf_pair() {
  host="$1"
  port="$2"
  seconds="${3:-8}"
  parallel="${4:-1}"
  bind_ip="${5:-}"
  upload_json="$(run_iperf_client "$host" "$port" 0 "$seconds" "$bind_ip" "$parallel" 2>/dev/null || true)"
  download_json="$(run_iperf_client "$host" "$port" 1 "$seconds" "$bind_ip" "$parallel" 2>/dev/null || true)"
  if ! printf '%s' "$upload_json" | grep -q '"end"'; then
    echo "ERR upload"
    return 1
  fi
  if ! printf '%s' "$download_json" | grep -q '"end"'; then
    echo "ERR download"
    return 1
  fi
  upload_bps="$(printf '%s\n' "$upload_json" | iperf_metric_or_unknown bps)"
  upload_retr="$(printf '%s\n' "$upload_json" | iperf_metric_or_unknown retrans)"
  upload_first="$(printf '%s\n' "$upload_json" | iperf_metric_or_unknown first)"
  download_bps="$(printf '%s\n' "$download_json" | iperf_metric_or_unknown bps)"
  download_retr="$(printf '%s\n' "$download_json" | iperf_metric_or_unknown retrans)"
  download_first="$(printf '%s\n' "$download_json" | iperf_metric_or_unknown first)"
  printf "%s %s %s %s %s %s\n" "$upload_bps" "$upload_retr" "$upload_first" "$download_bps" "$download_retr" "$download_first"
}

print_iperf_pair_rows() {
  pair_label="$1"
  values="$2"
  # shellcheck disable=SC2086
  set -- $values
  ui_row "$pair_label 上传" "$(format_rate "${1:-unknown}") / 重传 $(format_count "${2:-unknown}") 次 / 首秒 $(format_rate "${3:-unknown}")"
  ui_row "$pair_label 下载" "$(format_rate "${4:-unknown}") / 重传 $(format_count "${5:-unknown}") 次 / 首秒 $(format_rate "${6:-unknown}")"
}

write_tuning_profile() {
  title="$1"
  machine_role="$2"
  critical_direction="$3"
  protocol_class="$4"
  peer_label="$5"
  p1_result="$6"
  p4_result="$7"
  pmtu="$8"
  qdisc_delta_text="$9"
  params_text="${10:-}"
  backup_path="${11:-}"
  decision_text="${12:-}"
  ensure_state_dir
  mkdir -p "$(profiles_dir)"
  path="$(latest_profile_path)"
  {
    printf '# TCP-optimization 调参报告\n\n'
    printf -- '- 时间：%s\n' "$(date -Iseconds 2>/dev/null || date)"
    printf -- '- 标题：%s\n' "$(safe_report_text "$title")"
    printf -- '- 机器角色：%s\n' "$machine_role"
    printf -- '- 关键方向：%s\n' "$critical_direction"
    printf -- '- 协议类型：%s\n' "$protocol_class"
    printf -- '- 测试对端：%s\n' "$(mask_report_peer "$peer_label")"
    printf -- '- P1 结果：%s\n' "$(safe_report_text "$p1_result")"
    printf -- '- P4 结果：%s\n' "$(safe_report_text "$p4_result")"
    printf -- '- PMTU：%s\n' "$pmtu"
    printf -- '- qdisc delta：%s\n' "$(safe_report_text "$qdisc_delta_text")"
    printf -- '- 写入参数：%s\n' "$(safe_report_text "$params_text")"
    printf -- '- 备份路径：%s\n' "$(safe_report_text "$backup_path")"
    printf -- '- 保留原因：%s\n' "$(safe_report_text "$decision_text")"
    printf '\n> 本报告不保存 token、密码、SSH 私钥或 Cookie。\n'
  } > "$path"
  printf '%s\n' "$path"
}

advanced_diagnose_mode() {
  host=""
  port="$IPERF_PORT"
  seconds="8"
  machine_role="endpoint"
  critical_direction="download"
  protocol_class="unknown"
  proxy_software=""
  traffic_path=""
  while [ "$#" -gt 0 ]; do
    case "$1" in
      --peer|--host) require_option_value "$1" "${2:-}"; host="$2"; shift 2 ;;
      --port|--iperf-port) require_option_value "$1" "${2:-}"; port="$2"; shift 2 ;;
      --seconds) require_option_value "$1" "${2:-}"; seconds="$2"; shift 2 ;;
      --machine-role) require_option_value "$1" "${2:-}"; machine_role="$2"; shift 2 ;;
      --critical-direction) require_option_value "$1" "${2:-}"; critical_direction="$2"; shift 2 ;;
      --protocol-class) require_option_value "$1" "${2:-}"; protocol_class="$2"; shift 2 ;;
      --proxy-software) require_option_value "$1" "${2:-}"; proxy_software="$2"; shift 2 ;;
      --traffic-path) require_option_value "$1" "${2:-}"; traffic_path="$2"; shift 2 ;;
      *) die "未知 advanced-diagnose 参数：$1" ;;
    esac
  done
  [ -n "$host" ] || die "advanced-diagnose 需要 --host"
  validate_port_value "$port" || die "--port 必须在 1 和 65535 之间。"
  validate_positive_int_range "$seconds" 3 60 || die "--seconds 必须在 3 和 60 之间。"
  context_line="$(normalize_link_context "$machine_role" "$critical_direction" "$protocol_class" "$proxy_software" "$traffic_path")"
  machine_role="$(printf '%s\n' "$context_line" | cut -f1)"
  critical_direction="$(printf '%s\n' "$context_line" | cut -f2)"
  protocol_class="$(printf '%s\n' "$context_line" | cut -f3)"
  proxy_software="$(printf '%s\n' "$context_line" | cut -f4)"
  traffic_path="$(printf '%s\n' "$context_line" | cut -f5)"
  detect_os
  iface="$(route_iface_for_host "$host")"
  mtu="$(iface_mtu "$iface")"
  pmtu="$(probe_pmtu "$host")"
  rtt_ms="$(detect_rtt_ms "$host")"
  clear_screen
  print_header "高级链路诊断"
  ui_section "上下文"
  ui_row "机器角色" "$machine_role"
  ui_row "关键方向" "$critical_direction"
  ui_row "协议类型" "$protocol_class"
  [ -n "$proxy_software" ] && ui_row "代理软件" "$proxy_software"
  [ -n "$traffic_path" ] && ui_row "业务路径" "$traffic_path"
  ui_row "出口接口" "$iface"
  ui_row "接口 MTU" "$mtu"
  ui_row "PMTU" "$pmtu"
  ui_row "RTT" "${rtt_ms}ms"
  if [ "${DRY_RUN:-0}" = "1" ]; then
    ui_note "Dry Run" "只展示会采集的诊断项，不运行 iperf3，不写入系统。"
    return 0
  fi
  ensure_dependency iperf3 iperf3 || die "缺少 iperf3，无法进行高级诊断。"
  bind_ip="$(local_lan_ipv4 || true)"
  case "$host" in *:*) bind_ip="" ;; esac
  qdisc_before="$(qdisc_stats "$iface")"
  ui_section "P1 单流测试"
  p1_result="$(measure_iperf_pair "$host" "$port" "$seconds" 1 "$bind_ip")"
  print_iperf_pair_rows "P1" "$p1_result"
  ui_section "P4 多流容量探测"
  p4_result="$(measure_iperf_pair "$host" "$port" "$seconds" 4 "$bind_ip")"
  print_iperf_pair_rows "P4" "$p4_result"
  qdisc_after="$(qdisc_stats "$iface")"
  qdisc_delta_values="$(qdisc_delta "$qdisc_before" "$qdisc_after")"
  # shellcheck disable=SC2086
  set -- $qdisc_delta_values
  drop_delta="${1:-unknown}"
  backlog_delta="${2:-unknown}"
  ui_section "qdisc 测试窗口"
  ui_row "drop delta" "$drop_delta"
  ui_row "backlog delta" "$backlog_delta"
  ui_section "判断"
  if [ "$protocol_class" = "udp-quic" ]; then
    ui_note "协议" "UDP/QUIC 场景不应把 TCP iperf3 结论直接当成最终调参依据。"
  fi
  if [ "$drop_delta" = "0" ] && [ "$backlog_delta" = "0" ]; then
    ui_note "队列" "重传若仍偏高，更可能来自路径、对端或上游拥塞，不建议盲目堆大 buffer。"
  fi
  ui_note "强干预" "MTU、TBF/HTB、qos-agent 只给建议，不在本诊断中写入。"
}

# END src/tuning/diagnostics.sh

# BEGIN src/tuning/transaction.sh
# Module: src/tuning/transaction.sh
snapshot_managed_file() {
  backup_dir="$1"
  target_file="$2"
  label="$3"
  if [ -f "$target_file" ]; then
    cp "$target_file" "$backup_dir/$label.original" || return 1
    printf '1\n' > "$backup_dir/$label.existed"
  else
    printf '0\n' > "$backup_dir/$label.existed"
  fi
  printf '%s\n' "$target_file" > "$backup_dir/$label.path"
}

restore_managed_file() {
  backup_dir="$1"
  label="$2"
  target_file="$(cat "$backup_dir/$label.path" 2>/dev/null || true)"
  existed="$(cat "$backup_dir/$label.existed" 2>/dev/null || true)"
  [ -n "$target_file" ] || return 1
  case "$existed" in
    1)
      [ -f "$backup_dir/$label.original" ] || return 1
      atomic_copy_file "$backup_dir/$label.original" "$target_file" || return 1
      ;;
    0)
      rm -f "$target_file" || return 1
      ;;
    *)
      # 元数据缺失或损坏时拒绝恢复：不能把“不可信”当作“原本不存在”而删除现网文件。
      return 1
      ;;
  esac
}

sysctl_key_allowed_for_platform() {
  key="$1"
  detect_os
  case "$OS_FAMILY" in
    macos) return 1 ;;
    openwrt) openwrt_key_allowed "$key" ;;
    *) return 0 ;;
  esac
}

restore_runtime_values() {
  values_file="$1"
  [ -f "$values_file" ] || return 0
  transaction_failed=0
  while IFS='=' read -r key value || [ -n "$key" ]; do
    key="$(printf '%s' "$key" | sed 's/[[:space:]]*$//')"
    value="$(printf '%s' "$value" | sed 's/^[[:space:]]*//')"
    [ -n "$key" ] || continue
    sysctl -w "$key=$value" >/dev/null 2>&1 || transaction_failed=1
    actual="$(sysctl -n "$key" 2>/dev/null || true)"
    # 内核对多值项（如 tcp_rmem）以制表符分隔输出，比较前统一压缩为单空格。
    [ "$(printf '%s' "$actual" | tr -s '[:space:]' ' ')" = "$(printf '%s' "$value" | tr -s '[:space:]' ' ')" ] || transaction_failed=1
  done < "$values_file"
  [ "$transaction_failed" = "0" ]
}

apply_sysctl_transaction() {
  target_file="$1"
  candidate_file="$2"
  backup_dir="$3"
  label="$4"
  platform_is_read_only && macos_write_unsupported
  have_cmd sysctl || return 1
  snapshot_managed_file "$backup_dir" "$target_file" "$label" || return 1
  filtered="$backup_dir/$label.filtered"
  live="$backup_dir/$label.live"
  skipped="$backup_dir/$label.skipped"
  : > "$filtered"
  : > "$live"
  : > "$skipped"
  while IFS= read -r line || [ -n "$line" ]; do
    case "$line" in ''|'#'*) printf '%s\n' "$line" >> "$filtered"; continue ;; esac
    case "$line" in *=*) ;; *) printf '%s\n' "$line" >> "$skipped"; continue ;; esac
    key="$(printf '%s' "${line%%=*}" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    value="$(printf '%s' "${line#*=}" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    if ! sysctl_key_allowed_for_platform "$key"; then
      printf '%s unsupported-platform\n' "$key" >> "$skipped"
      continue
    fi
    current="$(sysctl -n "$key" 2>/dev/null || true)"
    if [ -z "$current" ]; then
      printf '%s unsupported-kernel\n' "$key" >> "$skipped"
      continue
    fi
    printf '%s = %s\n' "$key" "$current" >> "$live"
    printf '%s = %s\n' "$key" "$value" >> "$filtered"
  done < "$candidate_file"
  atomic_copy_file "$filtered" "$target_file" || return 1
  transaction_failed=0
  while IFS='=' read -r key value || [ -n "$key" ]; do
    case "$key" in ''|'#'*) continue ;; esac
    key="$(printf '%s' "$key" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    value="$(printf '%s' "$value" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    sysctl -w "$key=$value" >/dev/null 2>&1 || { transaction_failed=1; break; }
    actual="$(sysctl -n "$key" 2>/dev/null || true)"
    # 内核对多值项（如 tcp_rmem）以制表符分隔输出，比较前统一压缩为单空格。
    [ "$(printf '%s' "$actual" | tr -s '[:space:]' ' ')" = "$(printf '%s' "$value" | tr -s '[:space:]' ' ')" ] || { transaction_failed=1; break; }
  done < "$filtered"
  if [ "$transaction_failed" != "0" ]; then
    restore_runtime_values "$live" >/dev/null 2>&1 || true
    restore_managed_file "$backup_dir" "$label" >/dev/null 2>&1 || true
    return 1
  fi
  return 0
}

backup_state() {
  ensure_state_dir
  ts="$(date +%Y%m%d-%H%M%S)"
  dir="$(unique_path "$STATE_DIR/backups/$ts")"
  mkdir "$dir"
  snapshot_managed_file "$dir" "$SYSCTL_FILE" sysctl-file || return 1
  snapshot_managed_file "$dir" "$BASELINE_FILE" baseline-file || return 1
  : > "$dir/restore-current.conf"
  for key in \
    fs.file-max \
    net.ipv4.tcp_no_metrics_save \
    net.ipv4.tcp_ecn \
    net.ipv4.tcp_frto \
    net.ipv4.tcp_mtu_probing \
    net.ipv4.tcp_rfc1337 \
    net.ipv4.tcp_sack \
    net.ipv4.tcp_fack \
    net.ipv4.tcp_window_scaling \
    net.ipv4.tcp_adv_win_scale \
    net.ipv4.tcp_moderate_rcvbuf \
    net.ipv4.tcp_slow_start_after_idle \
    net.ipv4.tcp_fastopen \
    net.ipv4.tcp_notsent_lowat \
    net.ipv4.tcp_limit_output_bytes \
    net.ipv4.tcp_autocorking \
    net.core.rmem_max \
    net.core.wmem_max \
    net.core.netdev_max_backlog \
    net.core.somaxconn \
    net.core.optmem_max \
    net.ipv4.tcp_rmem \
    net.ipv4.tcp_wmem \
    net.ipv4.tcp_max_syn_backlog \
    net.ipv4.udp_rmem_min \
    net.ipv4.udp_wmem_min \
    net.core.default_qdisc \
    net.ipv4.tcp_congestion_control
  do
    value="$(sysctl -n "$key" 2>/dev/null || true)"
    [ -n "$value" ] || continue
    echo "$key = $value" >> "$dir/restore-current.conf"
  done
  sysctl -a 2>/dev/null | grep -E '^(fs.file-max|net\.core\.rmem_max|net\.core\.wmem_max|net\.ipv4\.tcp_|net\.ipv4\.udp_|net\.core\.default_qdisc|net\.ipv[46]\.conf\.)' > "$dir/sysctl-current.txt" || true
  if have_cmd tc && have_cmd ip; then
    ip link show > "$dir/ip-link.txt" 2>/dev/null || true
    tc qdisc show > "$dir/tc-qdisc.txt" 2>/dev/null || true
  fi
  echo "$dir"
}

write_sysctl_config() {
  profile="$1"
  output_file="${2:-$SYSCTL_FILE}"
  values="$(profile_values "$profile")"
  # shellcheck disable=SC2086
  set -- $values
  fs_file_max="$1"
  rmem_max="$2"
  wmem_max="$3"
  tcp_rmem_min="$4"
  tcp_rmem_default="$5"
  tcp_rmem_max="$6"
  tcp_wmem_min="$7"
  tcp_wmem_default="$8"
  tcp_wmem_max="$9"
  adv_win_scale="${10:-1}"
  notsent_lowat="${11:-16384}"
  qdisc="$(preferred_qdisc)"
  congestion="$(preferred_congestion_control)"
  [ -n "$congestion" ] || congestion="$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo cubic)"
  limit_output=131072

  cat > "$output_file" <<EOF
# Managed by TCP 双端调优器. Do not edit this block manually.
fs.file-max = $fs_file_max
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_ecn = 0
net.ipv4.tcp_frto = 0
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_rfc1337 = 0
net.ipv4.tcp_sack = 1
net.ipv4.tcp_fack = 1
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_adv_win_scale = $adv_win_scale
net.ipv4.tcp_moderate_rcvbuf = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_notsent_lowat = $notsent_lowat
net.core.rmem_max = $rmem_max
net.core.wmem_max = $wmem_max
net.core.netdev_max_backlog = 16384
net.core.somaxconn = 32768
net.core.optmem_max = 81920
net.ipv4.tcp_rmem = $tcp_rmem_min $tcp_rmem_default $tcp_rmem_max
net.ipv4.tcp_wmem = $tcp_wmem_min $tcp_wmem_default $tcp_wmem_max
net.ipv4.udp_rmem_min = 8192
net.ipv4.udp_wmem_min = 8192
net.core.default_qdisc = $qdisc
net.ipv4.tcp_congestion_control = $congestion
EOF
  if sysctl -n net.ipv4.tcp_limit_output_bytes >/dev/null 2>&1; then
    echo "net.ipv4.tcp_limit_output_bytes = $limit_output" >> "$output_file"
  fi
  if sysctl -n net.ipv4.tcp_autocorking >/dev/null 2>&1; then
    echo "net.ipv4.tcp_autocorking = 1" >> "$output_file"
  fi
}

apply_profile() {
  profile="$(normalize_profile "$1")"
  detect_os
  case "$OS_FAMILY" in
    macos) macos_write_unsupported ;;
    openwrt) DIE_EXIT_CODE="$EXIT_DEPENDENCY" die "OpenWrt 不允许写入大缓冲预设；请使用稳定优化或 local-minimal。" ;;
  esac
  if [ "${DRY_RUN:-0}" = "1" ]; then
    print_header "预制参数写入 · Dry Run"
    print_profile_summary "$profile"
    ui_note "动作" "只展示将写入的参数，不修改系统。"
    values="$(profile_values "$profile")"
    # shellcheck disable=SC2086
    set -- $values
    ui_row "tcp_rmem" "$4 $5 $6"
    ui_row "tcp_wmem" "$7 $8 $9"
    ui_row "BBR/qdisc" "bbr / $(preferred_qdisc)"
    return 0
  fi
  need_root
  backup_dir="$(backup_state)"
  candidate="$backup_dir/profile.candidate"
  write_sysctl_config "$profile" "$candidate"
  if ! apply_sysctl_transaction "$SYSCTL_FILE" "$candidate" "$backup_dir" profile-target; then
    restore_backup_dir "$backup_dir" >/dev/null 2>&1 || true
    DIE_EXIT_CODE="$EXIT_APPLY" die "sysctl 事务加载或验证失败，已回滚；备份目录：$backup_dir"
  fi
  atomic_write_line "$STATE_DIR/last-profile" "$profile"
  info "已即时保存并加载预设：$profile"
  info "备份目录：$backup_dir"
  status_short
}

apply_buffers() {
  rmem_max="$1"
  wmem_max="$2"
  adv_win_scale="${3:-2}"
  notsent_lowat="${4:-16384}"
  backlog="${5:-16384}"
  somaxconn="${6:-32768}"
  synbacklog="${7:-8192}"
  optmem="${8:-81920}"
  tcp_rmem_min="${TCP_TUNE_RMEM_MIN:-4096}"
  tcp_rmem_default="${TCP_TUNE_RMEM_DEFAULT:-87380}"
  tcp_wmem_min="${TCP_TUNE_WMEM_MIN:-4096}"
  tcp_wmem_default="${TCP_TUNE_WMEM_DEFAULT:-65536}"
  limit_output=""
  if [ "$#" -ge 9 ]; then
    limit_output="$9"
  else
    limit_output="$(awk -v n="$notsent_lowat" 'BEGIN {
      v = int(n * 2)
      if (v < 131072) v = 131072
      if (v > 1048576) v = 1048576
      printf "%d\n", v
    }')"
  fi
  qdisc="$(preferred_qdisc)"
  congestion="$(preferred_congestion_control)"
  [ -n "$congestion" ] || congestion="$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo cubic)"
  case "$rmem_max$wmem_max" in
    *[!0-9]*) die "buffer 参数必须是数字。" ;;
  esac
  is_integer "$adv_win_scale" || die "tcp_adv_win_scale 必须是整数。"
  for tcp_numeric in "$notsent_lowat" "$backlog" "$somaxconn" "$synbacklog" "$optmem" "$limit_output"; do
    is_unsigned_integer "$tcp_numeric" || die "扩展 TCP 参数必须是数字。"
  done
  if [ "${DRY_RUN:-0}" = "1" ]; then
    info "[dry-run] 将写入：rmem=$rmem_max wmem=$wmem_max adv=$adv_win_scale notsent=$notsent_lowat limit_output=$limit_output"
    return 0
  fi
  need_root
  detect_os
  case "$OS_FAMILY" in
    macos) macos_write_unsupported ;;
    openwrt)
      apply_openwrt_minimal_values 1 0 "$notsent_lowat" "$limit_output"
      return 0
      ;;
  esac
  backup_dir="$(backup_state)"
  candidate="$backup_dir/buffers.candidate"
  cat > "$candidate" <<EOF
# Managed by TCP 双端调优器. Auto-tuned buffers.
fs.file-max = 6815744
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_ecn = 0
net.ipv4.tcp_frto = 0
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_rfc1337 = 0
net.ipv4.tcp_sack = 1
net.ipv4.tcp_fack = 1
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_adv_win_scale = $adv_win_scale
net.ipv4.tcp_moderate_rcvbuf = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_notsent_lowat = $notsent_lowat
net.core.rmem_max = $rmem_max
net.core.wmem_max = $wmem_max
net.core.netdev_max_backlog = $backlog
net.core.somaxconn = $somaxconn
net.core.optmem_max = $optmem
net.ipv4.tcp_rmem = $tcp_rmem_min $tcp_rmem_default $rmem_max
net.ipv4.tcp_wmem = $tcp_wmem_min $tcp_wmem_default $wmem_max
net.ipv4.tcp_max_syn_backlog = $synbacklog
net.ipv4.udp_rmem_min = 8192
net.ipv4.udp_wmem_min = 8192
net.core.default_qdisc = $qdisc
net.ipv4.tcp_congestion_control = $congestion
EOF
  if sysctl -n net.ipv4.tcp_limit_output_bytes >/dev/null 2>&1; then
    echo "net.ipv4.tcp_limit_output_bytes = $limit_output" >> "$candidate"
  fi
  if sysctl -n net.ipv4.tcp_autocorking >/dev/null 2>&1; then
    echo "net.ipv4.tcp_autocorking = 1" >> "$candidate"
  fi
  if ! apply_sysctl_transaction "$SYSCTL_FILE" "$candidate" "$backup_dir" buffers-target; then
    restore_backup_dir "$backup_dir" >/dev/null 2>&1 || true
    DIE_EXIT_CODE="$EXIT_APPLY" die "sysctl 事务加载或验证失败，已回滚；备份目录：$backup_dir"
  fi
  if [ "${TUNE_SIMPLE_OUTPUT:-0}" = "1" ]; then
    info "参数已调整并即时保存（已创建回滚备份）。"
  else
    info "已即时保存并加载 buffer：rmem=$rmem_max wmem=$wmem_max notsent=$notsent_lowat limit_output=$limit_output"
    info "备份目录：$backup_dir"
  fi
}

apply_smart() {
  local_mbps="$1"
  peer_mbps="$2"
  rtt_ms="$3"
  memory_mb_value="$4"
  objective="$5"
  ramp_rate="${6:-0.79}"
  aggressive="${7:-0}"

  values="$(recommend_values "$local_mbps" "$peer_mbps" "$rtt_ms" "$memory_mb_value" "$objective" "$ramp_rate" "$aggressive")"
  case "$values" in
    ERR*) die "$values" ;;
  esac
  if [ "${DRY_RUN:-0}" = "1" ]; then
    print_recommendation "$local_mbps" "$peer_mbps" "$rtt_ms" "$memory_mb_value" "$objective" "$ramp_rate" "$aggressive"
    info "[dry-run] 不写入 sysctl。"
    return 0
  fi
  need_root
  # shellcheck disable=SC2086
  set -- $values
  apply_buffers "$1" "$2" "$3" "$4" "$5" "$6" "$7" "$8"
}

manual_backup_begin() {
  label="$1"
  ensure_state_dir
  ts="$(date +%Y%m%d-%H%M%S)"
  dir="$(unique_path "$STATE_DIR/manual-$label-$ts")"
  mkdir -p "$dir"
  : > "$dir/restore-current.conf"
  for key in \
    fs.file-max \
    net.ipv4.tcp_no_metrics_save \
    net.ipv4.tcp_ecn \
    net.ipv4.tcp_frto \
    net.ipv4.tcp_mtu_probing \
    net.ipv4.tcp_rfc1337 \
    net.ipv4.tcp_sack \
    net.ipv4.tcp_fack \
    net.ipv4.tcp_window_scaling \
    net.ipv4.tcp_adv_win_scale \
    net.ipv4.tcp_moderate_rcvbuf \
    net.ipv4.tcp_slow_start_after_idle \
    net.ipv4.tcp_fastopen \
    net.ipv4.tcp_notsent_lowat \
    net.ipv4.tcp_limit_output_bytes \
    net.ipv4.tcp_autocorking \
    net.core.rmem_max \
    net.core.wmem_max \
    net.core.netdev_max_backlog \
    net.core.somaxconn \
    net.core.optmem_max \
    net.ipv4.tcp_rmem \
    net.ipv4.tcp_wmem \
    net.ipv4.tcp_max_syn_backlog \
    net.ipv4.udp_rmem_min \
    net.ipv4.udp_wmem_min \
    net.core.default_qdisc \
    net.ipv4.tcp_congestion_control
  do
    value="$(sysctl -n "$key" 2>/dev/null || true)"
    [ -n "$value" ] || continue
    echo "$key = $value" >> "$dir/restore-current.conf"
  done
  sysctl -a 2>/dev/null | grep -E '^(fs.file-max|net\.core\.|net\.ipv4\.tcp_|net\.ipv4\.udp_)' > "$dir/before-sysctl.txt" || true
  snapshot_managed_file "$dir" "$VPS_ADAPT_FILE" vps-adapt || return 1
  snapshot_managed_file "$dir" "$OPENWRT_MINIMAL_FILE" openwrt-minimal || return 1
  snapshot_managed_file "$dir" "$SYSCTL_FILE" sysctl-file || return 1
  snapshot_managed_file "$dir" "$BASELINE_FILE" baseline-file || return 1
  echo "$dir"
}

ensure_initial_defaults_snapshot() {
  ensure_state_dir
  path_file="$(initial_defaults_path_file)"
  dir="$(cat "$path_file" 2>/dev/null || true)"
  if [ -n "$dir" ] && [ -d "$dir" ] && [ -f "$dir/restore-current.conf" ]; then
    printf '%s\n' "$dir"
    return 0
  fi
  dir="$(initial_defaults_dir)"
  if [ -d "$dir" ] && [ -f "$dir/restore-current.conf" ]; then
    atomic_write_line "$path_file" "$dir"
    printf '%s\n' "$dir"
    return 0
  fi
  tmp_dir="$(manual_backup_begin "initial-defaults")" || return 1
  if [ -e "$dir" ]; then
    dir="$(unique_path "$dir")"
  fi
  mv "$tmp_dir" "$dir"
  {
    printf 'created_at=%s\n' "$(date +%s)"
    printf 'role=%s\n' "${1:-local}"
    printf 'note=%s\n' "Initial TCP-optimization defaults snapshot. Restore only through restore-defaults."
  } > "$dir/metadata"
  atomic_write_line "$path_file" "$dir"
  printf '%s\n' "$dir"
}

ensure_initial_defaults_if_root() {
  if [ "$(id -u 2>/dev/null || echo 1)" != "0" ]; then
    return 1
  fi
  ensure_initial_defaults_snapshot "${1:-local}" >/dev/null 2>&1
}

restore_initial_defaults() {
  need_root
  path_file="$(initial_defaults_path_file)"
  dir="$(cat "$path_file" 2>/dev/null || true)"
  [ -n "$dir" ] || dir="$(initial_defaults_dir)"
  if [ ! -d "$dir" ] || [ ! -f "$dir/restore-current.conf" ]; then die "未找到首次运行默认值快照。"; fi
  restore_manual_backup "$dir"
  info "已恢复首次运行记录的默认值：$dir"
}

# END src/tuning/transaction.sh

# BEGIN src/tuning/rollback.sh
# Module: src/tuning/rollback.sh
restore_backup_dir() {
  backup_dir="$1"
  [ -n "$backup_dir" ] || return 1
  rollback_failed=0
  restore_runtime_values "$backup_dir/restore-current.conf" || rollback_failed=1
  if [ -f "$backup_dir/sysctl-file.path" ]; then
    restore_managed_file "$backup_dir" sysctl-file || rollback_failed=1
  fi
  if [ -f "$backup_dir/baseline-file.path" ]; then
    restore_managed_file "$backup_dir" baseline-file || rollback_failed=1
  fi
  # v0.1.x compatibility: old backups stored the managed files by basename.
  # They did not record whether a file originally existed, so only restore a
  # file that is actually present in the backup; never infer deletion.
  if [ ! -f "$backup_dir/sysctl-file.path" ] && [ -f "$backup_dir/99-tcp-tune.conf" ]; then
    atomic_copy_file "$backup_dir/99-tcp-tune.conf" "$SYSCTL_FILE" || rollback_failed=1
  fi
  legacy_baseline="$backup_dir/$(basename "$BASELINE_FILE")"
  if [ ! -f "$backup_dir/baseline-file.path" ] && [ -f "$legacy_baseline" ]; then
    atomic_copy_file "$legacy_baseline" "$BASELINE_FILE" || rollback_failed=1
  fi
  [ "$rollback_failed" = "0" ]
}

rollback_last() {
  need_root
  latest="$(latest_rollback_backup)"
  [ -n "$latest" ] || die "未找到可回滚备份。"
  case "$(basename "$latest")" in
    manual-*) restore_manual_backup "$latest" || return 1 ;;
    *) restore_backup_dir "$latest" || return 1 ;;
  esac
  mkdir -p "$STATE_DIR/rolled-back"
  rollback_target="$(unique_path "$STATE_DIR/rolled-back/$(basename "$latest")")"
  mv "$latest" "$rollback_target"
  info "已回滚到最近备份：$latest"
}

latest_rollback_backup() {
  {
    find "$STATE_DIR/backups" -mindepth 1 -maxdepth 1 -type d 2>/dev/null || true
    find "$STATE_DIR" -mindepth 1 -maxdepth 1 -type d -name 'manual-*' 2>/dev/null || true
  } | while IFS= read -r dir; do
    [ -d "$dir" ] || continue
    key="$(basename "$dir" | sed -n 's/.*\([0-9]\{8\}-[0-9]\{6\}\).*/\1/p' | tail -n 1)"
    [ -n "$key" ] || key="$(stat -c %Y "$dir" 2>/dev/null || stat -f %m "$dir" 2>/dev/null || echo 0)"
    printf '%s\t%s\n' "$key" "$dir"
  done | sort | tail -n 1 | cut -f2-
}

restore_manual_backup() {
  backup_dir="$1"
  [ -n "$backup_dir" ] || return 1
  [ -d "$backup_dir" ] || return 1
  rollback_failed=0
  for label in vps-adapt openwrt-minimal sysctl-file baseline-file; do
    [ -f "$backup_dir/$label.path" ] || continue
    restore_managed_file "$backup_dir" "$label" || rollback_failed=1
  done
  # v0.1.x manual backups used "<basename>.before". Keep this narrow
  # compatibility layer for project-managed files only; intentionally do not
  # restore the legacy sysctl.conf.before snapshot.
  for legacy_pair in \
    "$VPS_ADAPT_FILE:vps" \
    "$OPENWRT_MINIMAL_FILE:openwrt" \
    "$SYSCTL_FILE:sysctl" \
    "$BASELINE_FILE:baseline"
  do
    legacy_path=${legacy_pair%:*}
    legacy_file="$backup_dir/$(basename "$legacy_path").before"
    [ -f "$legacy_file" ] || continue
    atomic_copy_file "$legacy_file" "$legacy_path" || rollback_failed=1
  done
  restore_runtime_values "$backup_dir/restore-current.conf" || rollback_failed=1
  [ "$rollback_failed" = "0" ] || {
    warn "回滚校验失败，备份保留在：$backup_dir"
    return 1
  }
  info "已按手动备份回滚：$backup_dir"
}

initial_defaults_available() {
  path_file="$(initial_defaults_path_file)"
  dir="$(cat "$path_file" 2>/dev/null || true)"
  [ -n "$dir" ] || dir="$(initial_defaults_dir)"
  [ -d "$dir" ] && [ -f "$dir/restore-current.conf" ]
}

# END src/tuning/rollback.sh

# BEGIN src/agent/lifecycle.sh
# Module: src/agent/lifecycle.sh
random_token() {
  if have_cmd openssl; then
    openssl rand -hex 32
    return
  fi
  if have_cmd python3; then
    python3 -c 'import secrets; print(secrets.token_hex(32))'
    return
  fi
  return 1
}

write_agent_py() {
  path="$1"
  (umask 077; cat > "$path" <<'PY'
#!/usr/bin/env python3
"""Temporary, authenticated TCP-optimization HTTP agent."""

from __future__ import annotations

import collections
import hmac
import http.server
import ipaddress
import json
import math
import os
import signal
import socket
import subprocess
import threading
import time
from urllib.parse import parse_qs, urlparse

TOKEN = os.environ["TCP_TUNE_TOKEN"]
SCRIPT = os.environ["TCP_TUNE_SCRIPT"]
STATE_DIR = os.environ["TCP_TUNE_STATE_DIR"]
SESSION_ID = os.environ["TCP_TUNE_SESSION_ID"]
IPERF_PORT = int(os.environ.get("TCP_TUNE_IPERF_PORT", "5201"))
AGENT_PORT = int(os.environ.get("TCP_TUNE_AGENT_PORT", "39188"))
TTL = int(os.environ.get("TCP_TUNE_SESSION_TTL", "1800"))
BODY_LIMIT = int(os.environ.get("TCP_TUNE_AGENT_BODY_LIMIT", "32768"))
MAX_CONCURRENCY = int(os.environ.get("TCP_TUNE_AGENT_MAX_CONCURRENCY", "8"))
ALLOW_QUERY_TOKEN = os.environ.get("TCP_TUNE_ALLOW_QUERY_TOKEN", "0") == "1"
ALLOWED_TEST_HOSTS = {
    item.strip() for item in os.environ.get("TCP_TUNE_AGENT_TEST_ALLOWLIST", "").split(",") if item.strip()
}
ALLOWED_HOST_HEADERS = {
    item.strip().lower() for item in os.environ.get("TCP_TUNE_AGENT_ALLOWED_HOSTS", "").split(",") if item.strip()
}
STARTED = time.time()
STOP_EVENT = threading.Event()
SERVER_INSTANCE = None
STATE_LOCK = threading.Lock()
PROCESS_LOCK = threading.Lock()
REQUEST_SLOTS = threading.BoundedSemaphore(max(1, min(MAX_CONCURRENCY, 64)))
TEST_SLOT = threading.BoundedSemaphore(1)
ACTIVE_PROCESSES = set()
PEER_IP = None
STATE = {
    "started_at": STARTED,
    "session_id": SESSION_ID,
    "peer_reports": collections.deque(maxlen=100),
    "events": collections.deque(maxlen=200),
}


def text(value, limit=256):
    cleaned = "".join(ch if ch >= " " and ch != "\x7f" else " " for ch in str(value or ""))
    return cleaned[:limit]


def client_ip(handler):
    value = handler.client_address[0]
    if value.startswith("::ffff:"):
        value = value[7:]
    return value


def token_valid(handler):
    supplied = handler.headers.get("X-TCP-Tune-Token", "")
    if not supplied:
        auth = handler.headers.get("Authorization", "")
        supplied = auth[7:].strip() if auth.startswith("Bearer ") else ""
    if not supplied and ALLOW_QUERY_TOKEN:
        supplied = parse_qs(urlparse(handler.path).query).get("token", [""])[0]
    if not supplied:
        return False
    # compare_digest 对含非 ASCII 的 str 会抛 TypeError（客户端可控输入），统一按字节比较。
    try:
        supplied_bytes = supplied.encode("utf-8", "surrogateescape")
    except UnicodeEncodeError:
        return False
    return hmac.compare_digest(supplied_bytes, TOKEN.encode("utf-8"))


def host_header_valid(handler):
    value = handler.headers.get("Host", "")
    if not value or len(value) > 320 or any(ord(ch) < 33 for ch in value):
        return False
    try:
        parsed = urlparse("//" + value)
        if parsed.port not in (None, AGENT_PORT):
            return False
        hostname = (parsed.hostname or "").lower()
    except ValueError:
        return False
    return bool(hostname) and (not ALLOWED_HOST_HEADERS or hostname in ALLOWED_HOST_HEADERS)


def write_json(handler, code, payload):
    body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    handler.send_response(code)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Cache-Control", "no-store")
    handler.send_header("X-Content-Type-Options", "nosniff")
    handler.send_header("Content-Length", str(len(body)))
    handler.end_headers()
    try:
        handler.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError, socket.timeout):
        pass


def error(handler, status, code, message):
    write_json(handler, status, {"ok": False, "error": message, "error_code": code})


def read_json_body(handler):
    if handler.headers.get("Transfer-Encoding"):
        error(handler, 400, "unsupported_transfer_encoding", "chunked request bodies are not supported")
        return None
    raw_length = handler.headers.get("Content-Length")
    if raw_length is None:
        error(handler, 411, "length_required", "Content-Length is required")
        return None
    try:
        length = int(raw_length)
    except ValueError:
        error(handler, 400, "invalid_content_length", "invalid Content-Length")
        return None
    if length < 0 or length > BODY_LIMIT:
        error(handler, 413, "body_too_large", "request body too large")
        return None
    content_type = handler.headers.get("Content-Type", "").split(";", 1)[0].strip().lower()
    if length and content_type not in {"application/json", "application/problem+json"}:
        error(handler, 415, "unsupported_media_type", "application/json is required")
        return None
    raw = handler.rfile.read(length)
    if len(raw) != length:
        error(handler, 413, "body_too_large", "request body exceeds declared or allowed size")
        return None
    try:
        value = json.loads(raw.decode("utf-8")) if raw else {}
    except (UnicodeDecodeError, json.JSONDecodeError):
        error(handler, 400, "invalid_json", "invalid JSON body")
        return None
    if not isinstance(value, dict):
        error(handler, 400, "invalid_body", "request body must be an object")
        return None
    return value


def terminate_process(proc):
    if proc.poll() is not None:
        return
    try:
        os.killpg(proc.pid, signal.SIGTERM)
    except ProcessLookupError:
        return
    try:
        proc.wait(timeout=5)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass


def run_cmd(args, timeout):
    if args and args[0] == SCRIPT:
        args = ["/bin/sh", *args]
    try:
        proc = subprocess.Popen(args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
    except OSError as exc:
        return {"code": 126, "stdout": "", "stderr": f"unable to start fixed command: {exc.strerror or 'os error'}"}
    with PROCESS_LOCK:
        ACTIVE_PROCESSES.add(proc)
    try:
        try:
            stdout, stderr = proc.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            terminate_process(proc)
            stdout, stderr = proc.communicate()
            return {"code": 124, "stdout": stdout[-4000:], "stderr": (stderr + "\ncommand timed out")[-4000:]}
        return {"code": proc.returncode, "stdout": stdout[-4000:], "stderr": stderr[-4000:]}
    finally:
        with PROCESS_LOCK:
            ACTIVE_PROCESSES.discard(proc)


def terminate_active_processes():
    with PROCESS_LOCK:
        processes = list(ACTIVE_PROCESSES)
    for proc in processes:
        terminate_process(proc)


def strict_int(value, minimum, maximum):
    if isinstance(value, bool):
        return None
    try:
        number = int(value)
    except (TypeError, ValueError):
        return None
    if str(number) != str(value).strip() and not isinstance(value, int):
        return None
    return number if minimum <= number <= maximum else None


def report_number(value, minimum, maximum, integer=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if not math.isfinite(value) or value < minimum or value > maximum:
        return None
    if integer and int(value) != value:
        return None
    return int(value) if integer else value


def resolve_host(host):
    if not host or len(host) > 253 or host.startswith("-") or any(ord(ch) < 33 for ch in host):
        raise ValueError("invalid host")
    values = set()
    for item in socket.getaddrinfo(host, None, type=socket.SOCK_STREAM):
        values.add(str(ipaddress.ip_address(item[4][0])))
    if not values:
        raise ValueError("host did not resolve")
    return values


def test_target_allowed(host):
    try:
        addresses = resolve_host(host)
    except (ValueError, socket.gaierror):
        return False
    explicit = set()
    for allowed in ALLOWED_TEST_HOSTS:
        try:
            explicit.update(resolve_host(allowed))
        except (ValueError, socket.gaierror):
            continue
    with STATE_LOCK:
        peer = PEER_IP
    permitted = explicit | ({peer} if peer else set())
    return bool(permitted) and addresses.issubset(permitted)


def append_event(event):
    with STATE_LOCK:
        STATE["events"].append(event)


def format_rate(value):
    try:
        bps = float(value or 0)
    except (TypeError, ValueError):
        return "未检测"
    return f"{bps / 1_000_000_000:.2f} Gbps" if bps >= 1_000_000_000 else f"{bps / 1_000_000:.1f} Mbps"


def event_text(event):
    stamp = time.strftime("%H:%M:%S", time.localtime(float(event.get("time", 0))))
    action = event.get("action")
    if action == "peer-report" and event.get("round") is not None:
        direction = "上传" if event.get("direction") == "upload" else "下载"
        return f"{stamp} 第 {event.get('round')} 轮{direction}：{format_rate(event.get('bits_per_second'))}，重传 {event.get('retransmits', '未检测')} 次"
    labels = {"peer-report": "客户端上报", "test": "服务端测速任务", "restore-defaults": "恢复默认值", "stop-request": "停止会话"}
    return f"{stamp} {labels.get(str(action), text(action))}"


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "tcp-tune-agent/0.2"

    def setup(self):
        super().setup()
        self.connection.settimeout(10)

    def log_message(self, fmt, *args):
        return

    def _preflight(self):
        if time.time() - STARTED >= TTL or STOP_EVENT.is_set():
            error(self, 410, "session_expired", "session expired")
            return False
        if not host_header_valid(self):
            error(self, 400, "invalid_host_header", "invalid Host header")
            return False
        if not token_valid(self):
            error(self, 403, "invalid_token", "invalid token")
            return False
        return True

    def do_GET(self):
        if not REQUEST_SLOTS.acquire(blocking=False):
            error(self, 503, "busy", "agent concurrency limit reached")
            return
        try:
            if not self._preflight():
                return
            path = urlparse(self.path).path
            if path == "/state":
                with STATE_LOCK:
                    state = {"started_at": STARTED, "session_id": SESSION_ID, "peer_ip": PEER_IP}
                write_json(self, 200, {"ok": True, "iperf_port": IPERF_PORT, "state": state})
            elif path == "/events":
                with STATE_LOCK:
                    events = list(STATE["events"])
                    reports = list(STATE["peer_reports"])
                write_json(self, 200, {"ok": True, "events": events[-100:], "summaries": [event_text(v) for v in events[-30:]], "peer_reports": reports[-20:]})
            elif path == "/status":
                result = run_cmd([SCRIPT, "--json", "status"], 15)
                write_json(self, 200, {"ok": result["code"] == 0, "result": result})
            elif path == "/defaults":
                result = run_cmd([SCRIPT, "defaults-status"], 15)
                write_json(self, 200, {"ok": result["code"] == 0, "available": result["code"] == 0, "result": result})
            else:
                error(self, 404, "not_found", "not found")
        finally:
            REQUEST_SLOTS.release()

    def do_POST(self):
        if not REQUEST_SLOTS.acquire(blocking=False):
            error(self, 503, "busy", "agent concurrency limit reached")
            return
        try:
            if not self._preflight():
                return
            payload = read_json_body(self)
            if payload is None:
                return
            path = urlparse(self.path).path
            if path == "/report":
                self._report(payload)
            elif path == "/test":
                self._test(payload)
            elif path in {"/optimize", "/apply-profile", "/apply-buffers"}:
                error(self, 403, "server_read_only", "server is read-only")
            elif path == "/restore-defaults":
                if payload:
                    error(self, 400, "unknown_fields", "restore-defaults request body must be empty")
                    return
                result = run_cmd([SCRIPT, "restore-defaults"], 30)
                append_event({"time": time.time(), "action": "restore-defaults", "result": result["code"]})
                write_json(self, 200 if result["code"] == 0 else 500, {"ok": result["code"] == 0, "result": result})
            elif path == "/stop":
                if payload:
                    error(self, 400, "unknown_fields", "stop request body must be empty")
                    return
                append_event({"time": time.time(), "action": "stop-request"})
                write_json(self, 200, {"ok": True, "message": "agent stopping"})
                STOP_EVENT.set()
                threading.Thread(target=self.server.shutdown, daemon=True).start()
            else:
                error(self, 404, "not_found", "not found")
        finally:
            REQUEST_SLOTS.release()

    def _report(self, payload):
        global PEER_IP
        allowed = {"role", "lan_ip", "os", "architecture", "round", "rounds", "objective", "direction", "retransmits", "bits_per_second", "first_second_bits_per_second", "stage", "result", "detail", "time", "target_retr"}
        unknown = set(payload) - allowed
        if unknown:
            error(self, 400, "unknown_fields", "unknown report fields")
            return
        enums = {
            "objective": {"retrans", "throughput", "startup"},
            "direction": {"upload", "download", "both"},
            "stage": {"preset-probe", "preset-apply", "rollback", "auto", "restore-defaults"},
            "result": {"running", "ok", "success", "rollback", "failed"},
        }
        for key, choices in enums.items():
            if key in payload and payload[key] not in choices:
                error(self, 400, "invalid_report_parameters", "invalid report parameters")
                return
        numeric_fields = {
            "round": (1, 100, True),
            "rounds": (1, 100, True),
            "retransmits": (0, 1_000_000_000, True),
            "bits_per_second": (0, 1_000_000_000_000_000, False),
            "first_second_bits_per_second": (0, 1_000_000_000_000_000, False),
            "time": (0, 4_102_444_800, False),
            "target_retr": (0, 1_000_000_000, True),
        }
        normalized = {}
        for key, value in payload.items():
            if key in numeric_fields:
                if value is None:
                    normalized[key] = None
                    continue
                converted = report_number(value, *numeric_fields[key])
                if converted is None:
                    error(self, 400, "invalid_report_parameters", "invalid report parameters")
                    return
                normalized[key] = converted
            else:
                normalized[key] = text(value, 512 if key == "detail" else 256)
        if normalized.get("lan_ip"):
            try:
                ipaddress.ip_address(normalized["lan_ip"])
            except ValueError:
                error(self, 400, "invalid_report_parameters", "invalid report parameters")
                return
        source = client_ip(self)
        with STATE_LOCK:
            if PEER_IP is None:
                PEER_IP = source
            elif PEER_IP != source:
                error(self, 403, "peer_mismatch", "session is paired with another client")
                return
            report = {"time": time.time(), "payload": normalized}
            STATE["peer_reports"].append(report)
            event = {"time": time.time(), "action": "peer-report"}
            for key in allowed:
                if key in normalized:
                    event[key] = normalized[key]
            STATE["events"].append(event)
        write_json(self, 200, {"ok": True})

    def _test(self, payload):
        if set(payload) - {"host", "port", "seconds", "direction"}:
            error(self, 400, "unknown_fields", "unknown test fields")
            return
        host = str(payload.get("host", "")).strip()
        port = strict_int(payload.get("port", IPERF_PORT), 1, 65535)
        seconds = strict_int(payload.get("seconds", 10), 1, 60)
        direction = payload.get("direction", "download")
        if port is None or seconds is None or direction not in {"download", "upload"}:
            error(self, 400, "invalid_test_parameters", "invalid test parameters")
            return
        if not test_target_allowed(host):
            error(self, 403, "test_target_denied", "test target is not the paired client or allowlisted")
            return
        if not TEST_SLOT.acquire(blocking=False):
            error(self, 429, "test_busy", "another test is already running")
            return
        try:
            reverse = "1" if direction == "download" else "0"
            result = run_cmd([SCRIPT, "_iperf-json", host, str(port), reverse, str(seconds)], seconds + 15)
            append_event({"time": time.time(), "action": "test", "direction": direction, "result": result["code"]})
            write_json(self, 200 if result["code"] == 0 else 502, {"ok": result["code"] == 0, "result": result})
        finally:
            TEST_SLOT.release()


class DualStackThreadingHTTPServer(http.server.ThreadingHTTPServer):
    address_family = socket.AF_INET6
    daemon_threads = True

    def server_bind(self):
        try:
            self.socket.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)
        except OSError:
            pass
        super().server_bind()


def create_server():
    # TCP_TUNE_AGENT_BIND 允许把监听面收敛到内网/VPN 接口；默认保持双栈全接口。
    bind_address = os.environ.get("TCP_TUNE_AGENT_BIND", "").strip()
    if bind_address:
        if ":" in bind_address:
            return DualStackThreadingHTTPServer((bind_address, AGENT_PORT), Handler)
        return http.server.ThreadingHTTPServer((bind_address, AGENT_PORT), Handler)
    try:
        return DualStackThreadingHTTPServer(("::", AGENT_PORT), Handler)
    except OSError:
        return http.server.ThreadingHTTPServer(("0.0.0.0", AGENT_PORT), Handler)


def shutdown_signal(signum, frame):
    del signum, frame
    STOP_EVENT.set()
    if SERVER_INSTANCE is not None:
        threading.Thread(target=SERVER_INSTANCE.shutdown, daemon=True).start()


def ttl_watchdog(server):
    if not STOP_EVENT.wait(max(0, STARTED + TTL - time.time())):
        STOP_EVENT.set()
        server.shutdown()


if __name__ == "__main__":
    os.umask(0o077)
    server = create_server()
    SERVER_INSTANCE = server
    signal.signal(signal.SIGTERM, shutdown_signal)
    signal.signal(signal.SIGINT, shutdown_signal)
    watcher = threading.Thread(target=ttl_watchdog, args=(server,), daemon=True)
    watcher.start()
    try:
        server.serve_forever(poll_interval=0.25)
    finally:
        STOP_EVENT.set()
        server.server_close()
        terminate_active_processes()
        subprocess.Popen(
            ["/bin/sh", SCRIPT, "stop-agent", "--session", SESSION_ID],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
PY
  )
  chmod 700 "$path"
}

# 用 curl --config 传递鉴权头：token 不进入进程 argv，同机其他用户无法通过 ps 读取。
curl_with_token() {
  curl_token_value="$1"
  shift
  curl_header_cfg="$( (umask 077; mktemp "${TMPDIR:-/tmp}/tcp-tune-hdr.XXXXXX") 2>/dev/null )" || curl_header_cfg=""
  if [ -z "$curl_header_cfg" ]; then
    # 极少数无 mktemp 的环境退回请求头方式，保持功能可用。
    curl -H "X-TCP-Tune-Token: $curl_token_value" "$@"
    return
  fi
  printf 'header = "X-TCP-Tune-Token: %s"\n' "$curl_token_value" > "$curl_header_cfg"
  curl --config "$curl_header_cfg" "$@"
  curl_with_token_rc=$?
  rm -f "$curl_header_cfg"
  return "$curl_with_token_rc"
}

post_json() {
  url="$1"
  token="$2"
  data="$3"
  curl_with_token "$token" -fsS -H "Content-Type: application/json" -d "$data" "$url"
}

post_client_stage() {
  stage="$1"
  result="$2"
  detail="${3:-}"
  [ -n "${TUNE_REPORT_PEER:-}" ] || return 0
  [ -n "${TUNE_REPORT_TOKEN:-}" ] || return 0
  now="$(date +%s)"
  lan_ip="${TUNE_CLIENT_IP:-$(local_lan_ipv4 || true)}"
  data="{\"role\":\"client-stage\",\"lan_ip\":$(json_string "$lan_ip"),\"stage\":$(json_string "$stage"),\"result\":$(json_string "$result"),\"detail\":$(json_string "$detail"),\"time\":$now}"
  post_json "$TUNE_REPORT_PEER/report" "$TUNE_REPORT_TOKEN" "$data" >/dev/null 2>&1 || true
}

listen_mode() {
  need_root
  install_runtime_deps
  ensure_dependency python3 python3 || die "listen 模式需要 python3 运行临时 HTTP Agent。"
  ensure_state_dir
  umask 077
  lock_root="$STATE_DIR/locks"
  lock_dir="$lock_root/agent-$AGENT_PORT.lock"
  mkdir -p "$lock_root"
  chmod 700 "$lock_root" 2>/dev/null || true
  if [ "${DRY_RUN:-0}" = "1" ]; then
    # dry-run 只检查、不获取会话锁：中途任何异常（如输出管道被关闭）都不会遗留锁。
    if [ -d "$lock_dir" ]; then
      DIE_EXIT_CODE="$EXIT_NETWORK" die "Agent 端口 $AGENT_PORT 已有会话锁；请先运行 stop-agent 并确认旧会话已结束。"
    fi
    ensure_initial_defaults_snapshot "server" >/dev/null || warn "无法记录服务端首次默认值快照，恢复默认值菜单将只恢复客户端。"
    if [ -n "$LISTEN_PUBLIC_URL" ]; then
      peer_url="$LISTEN_PUBLIC_URL"
    else
      peer_url="http://<公网IP>:$AGENT_PORT"
    fi
    token="<启动后自动生成>"
    echo "[dry-run] 将启动临时 HTTP Agent：${TCP_TUNE_AGENT_BIND:-[::]}:$AGENT_PORT（未设 TCP_TUNE_AGENT_BIND 时失败回退 0.0.0.0）"
    echo "[dry-run] 将启动 iperf3 server：0.0.0.0:$IPERF_PORT"
    echo "[dry-run] 会话 TTL：$SESSION_TTL 秒"
    print_client_commands "$peer_url" "$token"
    return 0
  fi
  if ! mkdir "$lock_dir" 2>/dev/null; then
    DIE_EXIT_CODE="$EXIT_NETWORK" die "Agent 端口 $AGENT_PORT 已有会话锁；请先运行 stop-agent 并确认旧会话已结束。"
  fi
  ensure_initial_defaults_snapshot "server" >/dev/null || warn "无法记录服务端首次默认值快照，恢复默认值菜单将只恢复客户端。"

  token="$(random_token)" || { rmdir "$lock_dir" 2>/dev/null || true; DIE_EXIT_CODE="$EXIT_DEPENDENCY" die "无法获得安全随机源，拒绝启动 Agent。"; }
  session_id="$(random_token)" || { rmdir "$lock_dir" 2>/dev/null || true; DIE_EXIT_CODE="$EXIT_DEPENDENCY" die "无法生成会话标识。"; }
  script_path="$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)/$(basename -- "$0")"
  agent_py="$STATE_DIR/tcp-tune-agent-$AGENT_PORT.py"
  write_agent_py "$agent_py"
  TCP_TUNE_SESSION_ID="$session_id"
  export TCP_TUNE_SESSION_ID
  start_iperf_server "$IPERF_PORT"

  export TCP_TUNE_TOKEN="$token"
  export TCP_TUNE_SCRIPT="$script_path"
  export TCP_TUNE_AGENT_PORT="$AGENT_PORT"
  export TCP_TUNE_IPERF_PORT="$IPERF_PORT"
  export TCP_TUNE_SESSION_TTL="$SESSION_TTL"
  export TCP_TUNE_STATE_DIR="$STATE_DIR"
  export TCP_TUNE_AGENT_BODY_LIMIT TCP_TUNE_AGENT_MAX_CONCURRENCY TCP_TUNE_AGENT_TEST_ALLOWLIST TCP_TUNE_ALLOW_QUERY_TOKEN
  export TCP_TUNE_AGENT_BIND="${TCP_TUNE_AGENT_BIND:-}"

  nohup python3 "$agent_py" > "$STATE_DIR/agent-$AGENT_PORT.log" 2>&1 &
  agent_pid="$!"
  atomic_write_line "$STATE_DIR/agent-$AGENT_PORT.pid" "$agent_pid"
  write_process_manifest "$STATE_DIR/agent-$AGENT_PORT.manifest" "$agent_pid" "$session_id" "$agent_py" "$AGENT_PORT" || {
    kill "$agent_pid" 2>/dev/null || true
    stop_iperf_server "$IPERF_PORT" >/dev/null 2>&1 || true
    rm -f "$lock_dir/session" 2>/dev/null || true
    rmdir "$lock_dir" 2>/dev/null || true
    DIE_EXIT_CODE="$EXIT_NETWORK" die "无法记录 Agent 进程身份。"
  }

  if [ -n "$LISTEN_PUBLIC_URL" ]; then
    peer_url="$LISTEN_PUBLIC_URL"
  else
    ip="$(public_ip)"
    [ -n "$ip" ] || ip="<公网IP>"
    peer_url="http://$ip:$AGENT_PORT"
  fi
  atomic_write_line "$STATE_DIR/agent-$AGENT_PORT.token" "$token"
  atomic_write_line "$STATE_DIR/agent-$AGENT_PORT.url" "$peer_url"
  atomic_write_line "$lock_dir/session" "$session_id"
  ready=0
  check_url="http://127.0.0.1:$AGENT_PORT/state"
  ready_try=0
  while [ "$ready_try" -lt 10 ]; do
    if curl_with_token "$token" -fsS --max-time 2 "$check_url" >/dev/null 2>&1; then
      ready=1
      break
    fi
    kill -0 "$agent_pid" 2>/dev/null || break
    sleep 1
    ready_try=$((ready_try + 1))
  done
  if [ "$ready" != "1" ]; then
    stop_agent --session "$session_id" >/dev/null 2>&1 || true
    DIE_EXIT_CODE="$EXIT_NETWORK" die "Agent 未通过启动就绪检查，请查看 $STATE_DIR/agent-$AGENT_PORT.log。"
  fi
  if [ "${SERVER_MONITOR_AFTER_LISTEN:-0}" != "1" ]; then
    render_server_dashboard "$peer_url" "$token"
  fi
}

stop_agent() {
  need_root
  ensure_state_dir
  expected_session=""
  if [ "${1:-}" = "--session" ]; then
    expected_session="${2:-}"
    [ -n "$expected_session" ] || return 2
  fi
  stopped=0
  cleaned_agent_ports=""
  cleaned_sessions=""
  for manifest in "$STATE_DIR"/agent-*.manifest "$STATE_DIR"/iperf3-*.manifest; do
    [ -f "$manifest" ] || continue
    session="$(manifest_value "$manifest" session)"
    [ -z "$expected_session" ] || [ "$session" = "$expected_session" ] || continue
    pid="$(manifest_value "$manifest" pid)"
    process_port="$(manifest_value "$manifest" port)"
    if stop_verified_process "$manifest" "$expected_session"; then
      rm -f "$manifest"
      case "$manifest" in
        *agent-*) rm -f "${manifest%.manifest}.pid"; cleaned_agent_ports="$cleaned_agent_ports $process_port" ;;
        *iperf3-*) rm -f "${manifest%.manifest}.pid" ;;
      esac
      cleaned_sessions="$cleaned_sessions $session"
      stopped=1
    elif ! kill -0 "$pid" 2>/dev/null; then
      rm -f "$manifest" "${manifest%.manifest}.pid"
      case "$manifest" in *agent-*) cleaned_agent_ports="$cleaned_agent_ports $process_port" ;; esac
      cleaned_sessions="$cleaned_sessions $session"
    fi
  done
  for process_port in $cleaned_agent_ports; do
    rm -f "$STATE_DIR/agent-$process_port.token" "$STATE_DIR/agent-$process_port.url" \
      "$STATE_DIR/tcp-tune-agent-$process_port.py" "$STATE_DIR/server-dashboard-$process_port.json"
  done
  for lock_dir in "$STATE_DIR"/locks/agent-*.lock; do
    [ -d "$lock_dir" ] || continue
    lock_session="$(cat "$lock_dir/session" 2>/dev/null || true)"
    clean_lock=0
    for session in $cleaned_sessions; do [ "$lock_session" = "$session" ] && clean_lock=1; done
    [ "$clean_lock" = "1" ] || continue
    rm -f "$lock_dir/session"
    rmdir "$lock_dir" 2>/dev/null || true
  done
  if [ "$stopped" = "0" ]; then
    info "未发现本工具记录的临时 Agent/iperf3 pid。"
  else
    info "已停止本工具记录的临时进程。"
  fi
}

# END src/agent/lifecycle.sh

# BEGIN src/cli/server-dashboard.sh
# Module: src/cli/server-dashboard.sh
get_agent_json() {
  url="$1"
  token="$2"
  curl_with_token "$token" -fsS "$url"
}

remote_defaults_available() {
  peer="$1"
  token="$2"
  # Agent 输出紧凑 JSON（"available":true 无空格），匹配必须容忍两种格式。
  curl_with_token "$token" -fsS --max-time 3 "$peer/defaults" 2>/dev/null | grep -Eq '"available"[[:space:]]*:[[:space:]]*true'
}

defaults_menu_tag() {
  peer="$1"
  token="$2"
  if initial_defaults_available; then
    local_tag="本机已记录"
  else
    local_tag="本机未记录"
  fi
  if remote_defaults_available "$peer" "$token"; then
    remote_tag="服务端已记录"
  else
    remote_tag="服务端未知"
  fi
  printf '[%s / %s]\n' "$local_tag" "$remote_tag"
}

restore_defaults_menu() {
  peer="$1"
  token="$2"
  clear_screen
  print_header "恢复默认值"
  ui_subtitle "恢复客户端首次运行时记录的本机参数，并请求服务端恢复启动时快照。"
  echo
  ui_section "快照状态"
  if initial_defaults_available; then
    ui_row "本机快照" "已记录"
  else
    ui_row "本机快照" "未记录"
  fi
  if remote_defaults_available "$peer" "$token"; then
    ui_row "服务端快照" "已记录"
  else
    ui_row "服务端快照" "未知或不可用"
  fi
  echo
  ui_note "范围" "只恢复本工具首次运行记录的 TCP/sysctl 相关参数，不修改防火墙、DNS、代理或路由策略。"
  ui_note "区别" "回滚最近修改只撤销最近一次写入；恢复默认值会回到首次连接时记录的基线。"
  echo
  if ! prompt_read "确认恢复默认值？输入 yes 继续，其他返回："; then
    return 1
  fi
  [ "$PROMPT_REPLY" = "yes" ] || return 0

  local_ok="0"
  remote_ok="0"
  if initial_defaults_available; then
    if restore_initial_defaults; then
      local_ok="1"
    else
      warn "本机默认值恢复失败。"
    fi
  else
    warn "本机没有首次默认值快照，跳过本机恢复。"
  fi

  if post_json "$peer/restore-defaults" "$token" "{}" >/dev/null 2>&1; then
    remote_ok="1"
  else
    warn "服务端默认值恢复请求失败。"
  fi

  if [ "$local_ok" = "1" ] || [ "$remote_ok" = "1" ]; then
    post_client_stage "restore-defaults" "success" "本机:$local_ok 服务端:$remote_ok"
    ui_note "结果" "恢复默认值流程已执行。本机=$local_ok，服务端=$remote_ok。"
    return 0
  fi
  post_client_stage "restore-defaults" "failed" "没有可恢复快照"
  return 1
}

render_agent_events_summary() {
  peer="$1"
  token="$2"
  json="$(get_agent_json "$peer/events" "$token")" || return 1
  if have_cmd python3; then
    tmp_events="$STATE_DIR/events-summary.json"
    mkdir -p "$STATE_DIR" 2>/dev/null || true
    printf '%s' "$json" > "$tmp_events"
    python3 - "$tmp_events" <<'PY'
import json
import sys

with open(sys.argv[1], "r", encoding="utf-8") as handle:
    data = json.load(handle)
summaries = data.get("summaries") or []
if not summaries:
    print("  暂无过程记录。")
else:
    for line in summaries[-30:]:
        print(f"  {line}")
PY
    return 0
  fi
  printf '%s\n' "$json" | awk '
    /"summaries"[[:space:]]*:/ { in_summaries=1; next }
    in_summaries && /\]/ { in_summaries=0; next }
    in_summaries {
      line=$0
      sub(/^[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      gsub(/\\"/, "\"", line)
      if (line != "") print "  " line
      found=1
    }
    END {
      if (!found) print "  暂无过程记录。"
    }
  '
}

render_server_dashboard() {
  peer_url="$1"
  token="$2"
  remaining="${3:-$SESSION_TTL}"
  ttl_text="$((remaining / 60))m $((remaining % 60))s"
  clear_screen
  print_header "TCP 双端调优器 · 服务端监控"
  ui_subtitle "服务端只负责接收客户端、展示过程和提供临时测速服务"
  echo
  ui_section "会话状态"
  ui_row "运行状态" "服务运行中"
  ui_row "运行模式" "只读监控"
  ui_row "Agent 端口" "$AGENT_PORT"
  ui_row "测速端口" "$IPERF_PORT"
  ui_row "剩余时间" "$ttl_text"
  echo
  render_server_activity "$token"
  echo
  print_client_commands "$peer_url" "$token"
  echo
  ui_section "安全说明"
  ui_note "只读" "服务端不修改 TCP 参数，所有优化由客户端在本机执行。"
  ui_note "刷新" "连接命令不会反复重绘；底部状态行会原地刷新，方便复制。"
  ui_note "清理" "保持此窗口运行；按 Ctrl+C 会停止 Agent/iperf3 并清理凭据。"
}

render_server_activity() {
  token="$1"
  dashboard_file="$STATE_DIR/server-dashboard-$AGENT_PORT.json"
  if ! curl_with_token "$token" -fsS "http://127.0.0.1:$AGENT_PORT/state" -o "$dashboard_file" 2>/dev/null; then
    printf "%s会话状态%s\n" "$COLOR_BOLD$COLOR_CYAN" "$COLOR_RESET"
    print_rule
    echo "  Agent 状态暂时不可读。"
    return 0
  fi
  python3 - "$dashboard_file" <<'PY'
import json
import sys
import time

with open(sys.argv[1], "r", encoding="utf-8") as handle:
    state = json.load(handle).get("state", {})

reports = state.get("peer_reports", [])
devices = {}
results = []
stages = []
for entry in reports:
    payload = entry.get("payload", {})
    ip = str(payload.get("lan_ip") or "").strip()
    role = str(payload.get("role") or "unknown")
    if payload.get("bits_per_second") is not None:
        results.append((entry.get("time", 0), payload))
    if payload.get("stage"):
        stages.append((entry.get("time", 0), payload))
    if ip:
        device = devices.setdefault(ip, {"ip": ip, "os": "Unknown", "role": role, "last": 0})
        if payload.get("os"):
            device["os"] = str(payload["os"])
        if role != "client-result":
            device["role"] = role
        device["last"] = max(device["last"], entry.get("time", 0))

print("  ▎ 已接入客户端")
if not devices:
    print("  暂无客户端，等待连接...")
else:
    for device in sorted(devices.values(), key=lambda item: item["last"], reverse=True):
        seen = time.strftime("%H:%M:%S", time.localtime(device["last"]))
        print(f"  ● {device['os']} · {device['ip']}  最近上报 {seen}")

print()
print("  ▎ 客户端状态")
if not stages:
    print("  当前状态  空闲 / 未开始")
    print("  最近结论  未开始")
else:
    _, payload = stages[-1]
    stage_name = {
        "preset-probe": "预制参数检测",
        "preset-apply": "预制参数写入",
        "rollback": "回滚",
        "auto": "稳定自动优化",
    }.get(str(payload.get("stage") or ""), str(payload.get("stage") or "任务"))
    result_name = {
        "running": "进行中",
        "ok": "完成",
        "success": "成功",
        "rollback": "已回滚",
        "failed": "失败",
    }.get(str(payload.get("result") or ""), str(payload.get("result") or ""))
    detail = str(payload.get("detail") or "")
    print(f"  当前状态  {stage_name} {result_name}".rstrip())
    print(f"  最近结论  {detail or result_name or '未开始'}")

print()
print("  ▎ 最近结果")
if not results:
    print("  尚未收到测速结果。")
else:
    _, payload = results[-1]
    objective = {"retrans": "重传优先", "throughput": "吞吐优先", "startup": "快速起速"}.get(str(payload.get("objective")), "未指定")
    direction = {"upload": "上传", "download": "下载", "both": "双向"}.get(payload.get("direction"), "未检测")
    bps = payload.get("bits_per_second") if isinstance(payload.get("bits_per_second"), (int, float)) and not isinstance(payload.get("bits_per_second"), bool) else None
    rate = "未检测" if bps is None else (f"{bps / 1_000_000_000:.2f} Gbps" if bps >= 1_000_000_000 else f"{bps / 1_000_000:.1f} Mbps")
    retransmits = payload.get("retransmits") if isinstance(payload.get("retransmits"), int) and not isinstance(payload.get("retransmits"), bool) else None
    first_bps = payload.get("first_second_bits_per_second") if isinstance(payload.get("first_second_bits_per_second"), (int, float)) and not isinstance(payload.get("first_second_bits_per_second"), bool) else None
    first_rate = "未检测" if first_bps is None else (f"{first_bps / 1_000_000_000:.2f} Gbps" if first_bps >= 1_000_000_000 else f"{first_bps / 1_000_000:.1f} Mbps")
    round_no = payload.get("round") or "-"
    rounds = payload.get("rounds") or "-"
    print(f"  模式  {objective}")
    print(f"  方向  {direction}")
    print(f"  轮次  {round_no}/{rounds}")
    print(f"  速度  {rate}")
    print(f"  重传  {'未检测' if retransmits is None else format(retransmits, ',') + ' 次'}")
    if first_bps is not None:
        print(f"  首秒  {first_rate}")
    print("  判定  已收到结果，等待客户端复测或下一步操作")

print()
print("  ▎ 最近事件")
events = state.get("events", [])[-5:]
if not events:
    print("  服务端已启动，等待客户端上报。")
else:
    for event in events:
        stamp = time.strftime("%H:%M:%S", time.localtime(event.get("time", 0)))
        if event.get("action") == "peer-report" and event.get("stage"):
            stage = {"preset-probe": "预制参数检测", "preset-apply": "预制参数写入", "rollback": "回滚"}.get(event.get("stage"), event.get("stage"))
            status = {"running": "进行中", "ok": "完成", "success": "成功", "rollback": "已回滚", "failed": "失败"}.get(event.get("result"), event.get("result"))
            text = f"{stage} {status}".strip()
        elif event.get("action") == "peer-report" and event.get("round") is not None:
            text = f"收到第 {event.get('round')} 轮测速结果"
        elif event.get("action") == "peer-report":
            text = f"客户端上报：{event.get('lan_ip') or event.get('role', 'unknown')}"
        elif event.get("action") == "test":
            text = "服务端测速任务完成"
        elif event.get("action") == "stop-request":
            text = "收到停止会话请求"
        else:
            text = str(event.get("action") or "事件")
        print(f"  {stamp}  {text}")
PY
}

server_compact_status_line() {
  token="$1"
  remaining="${2:-0}"
  ttl_text="$((remaining / 60))m $((remaining % 60))s"
  dashboard_file="$STATE_DIR/server-compact-$AGENT_PORT.json"
  if ! curl_with_token "$token" -fsS "http://127.0.0.1:$AGENT_PORT/state" -o "$dashboard_file" 2>/dev/null; then
    printf "刷新 %s | 剩余 %s | Agent 状态暂不可读" "$(date '+%H:%M:%S')" "$ttl_text"
    return 0
  fi
  python3 - "$dashboard_file" "$ttl_text" <<'PY'
import json
import sys
import time

path, ttl_text = sys.argv[1], sys.argv[2]
try:
    with open(path, "r", encoding="utf-8") as handle:
        state = json.load(handle).get("state", {})
except Exception:
    state = {}

reports = state.get("peer_reports", [])
devices = {}
latest_result = None
latest_stage = None
for entry in reports:
    payload = entry.get("payload", {})
    stamp = entry.get("time", 0)
    ip = str(payload.get("lan_ip") or "").strip()
    if ip:
        devices[ip] = max(devices.get(ip, 0), stamp)
    if payload.get("bits_per_second") is not None:
        latest_result = payload
    if payload.get("stage"):
        latest_stage = payload

status = "空闲"
conclusion = "未开始"
if latest_stage:
    stage_map = {
        "preset-probe": "预制检测",
        "preset-apply": "预制写入",
        "rollback": "回滚中",
        "auto": "稳定优化",
    }
    result_map = {
        "running": "进行中",
        "ok": "完成",
        "success": "成功",
        "rollback": "已回滚",
        "failed": "失败",
    }
    status = stage_map.get(str(latest_stage.get("stage") or ""), str(latest_stage.get("stage") or "任务"))
    conclusion = result_map.get(str(latest_stage.get("result") or ""), str(latest_stage.get("result") or "进行中"))

result_text = "暂无测速"
if latest_result:
    raw_bps = latest_result.get("bits_per_second")
    bps = raw_bps if isinstance(raw_bps, (int, float)) and not isinstance(raw_bps, bool) else None
    rate = "未检测" if bps is None else (f"{bps / 1_000_000_000:.2f}Gbps" if bps >= 1_000_000_000 else f"{bps / 1_000_000:.1f}Mbps")
    raw_retrans = latest_result.get("retransmits")
    retransmits = raw_retrans if isinstance(raw_retrans, int) and not isinstance(raw_retrans, bool) else None
    direction = {"upload": "上传", "download": "下载", "both": "双向"}.get(latest_result.get("direction"), "未检测")
    retrans_text = "未检测" if retransmits is None else f"{retransmits:,} 次"
    result_text = f"{direction} {rate} / 重传 {retrans_text}"

print(
    f"刷新 {time.strftime('%H:%M:%S')} | 剩余 {ttl_text} | "
    f"客户端 {len(devices)} | 状态 {status} | 最近 {result_text} | 判定 {conclusion}",
    end="",
)
PY
}

server_monitor() {
  token_file="$STATE_DIR/agent-$AGENT_PORT.token"
  url_file="$STATE_DIR/agent-$AGENT_PORT.url"
  agent_pid_file="$STATE_DIR/agent-$AGENT_PORT.pid"
  token="$(cat "$token_file" 2>/dev/null || true)"
  peer_url="$(cat "$url_file" 2>/dev/null || true)"
  [ -n "$token" ] || die "服务端 token 文件不存在。"
  deadline=$(( $(date +%s) + SESSION_TTL ))
  rendered_once=0
  while true; do
    if [ ! -f "$agent_pid_file" ]; then
      [ -t 1 ] && [ "$rendered_once" = "1" ] && echo
      info "服务端会话已停止。"
      return 0
    fi
    agent_pid="$(cat "$agent_pid_file" 2>/dev/null || true)"
    if [ -z "$agent_pid" ] || ! kill -0 "$agent_pid" >/dev/null 2>&1; then
      [ -t 1 ] && [ "$rendered_once" = "1" ] && echo
      warn "Agent 已退出，服务端监控结束。"
      return 0
    fi
    now="$(date +%s)"
    remaining=$((deadline - now))
    if [ "$remaining" -le 0 ]; then
      [ -t 1 ] && [ "$rendered_once" = "1" ] && echo
      warn "会话已达到 TTL，正在安全停止。"
      return 0
    fi
    if [ -t 1 ]; then
      if [ "$rendered_once" = "0" ]; then
        render_server_dashboard "$peer_url" "$token" "$remaining"
        echo
        rendered_once=1
      fi
      printf "\r\033[K%s" "$(server_compact_status_line "$token" "$remaining")"
    elif [ "$rendered_once" = "0" ]; then
      render_server_dashboard "$peer_url" "$token" "$remaining"
      rendered_once=1
    fi
    sleep 2
  done
}

render_client_dashboard() {
  peer_url="$1"
  local_ip="$2"
  iperf_port="$3"
  clear_screen
  print_header "TCP 双端调优器 · 客户端"
  ui_subtitle "${OS_NAME:-本机} 设备已连接，可直接选择优化目标"
  echo
  ui_section "连接状态"
  ui_row "会话" "已连接"
  ui_row "本机" "${OS_NAME:-Unknown} · ${local_ip:-未识别}"
  ui_row "测速节点" "已连接的服务端"
  ui_row "测试端口" "$iperf_port"
  echo
  ui_note "提示" "代理/公网地址仅用于脚本通讯，界面和测试源地址优先使用本机局域网 IP。"
}

print_client_commands() {
  peer_url="$1"
  token="$2"
  display_token="$token"
  case "$display_token" in
    \<*\>) ;;
    *)
      if [ ! -t 1 ]; then
        display_token="<会话令牌已隐藏>"
      fi
      ;;
  esac
  ui_section "客户端连接命令"
  ui_note "令牌" "交互终端显示完整 token；非交互输出会隐藏 token。"
  ui_note "安全" "多用户客户端主机上建议先 export TCP_TUNE_TOKEN=<令牌> 再省略 --token，避免 token 进入 shell history。"
  printf "%sOpenWrt / Linux / macOS%s\n" "$COLOR_CYAN" "$COLOR_RESET"
  cat <<EOF
  curl -fsSL $RAW_BASE_URL/tcp-tune.sh | \\
    sh -s -- --yes client \\
      --peer $peer_url \\
      --token $display_token \\
      --iperf-port $IPERF_PORT
EOF
  echo
  printf "%s短命令模式%s\n" "$COLOR_CYAN" "$COLOR_RESET"
  cat <<EOF
  curl -fsSL $RAW_BASE_URL/tcp-tune.sh -o tcp-tune.sh
  sh tcp-tune.sh --yes client \\
    --peer $peer_url \\
    --token $display_token \\
    --iperf-port $IPERF_PORT
EOF
  echo
  printf "%sWindows PowerShell%s\n" "$COLOR_CYAN" "$COLOR_RESET"
  cat <<EOF
  iwr -UseBasicParsing $RAW_BASE_URL/tcp-tune.ps1 -OutFile tcp-tune.ps1
  .\\tcp-tune.ps1 client \`
    -Peer $peer_url \`
    -Token $display_token \`
    -IperfPort $IPERF_PORT \`
    -Direction download -Yes
EOF
}

